// 自動生成ファイル(編集は questions.json に対して行い、node scripts/build-data.js を実行)
window.STAT2_QUESTIONS=[{"id":"yoso-01","field":"データの基礎","question":"5個のデータ 3, 5, 6, 8, 13 の不偏分散(n−1で割る分散)はいくつか。","choices":["11.6","12.9","14.5","58.0"],"answer":3,"explanation":"平均は7。偏差平方和は16+4+1+1+36=58。n−1=4で割って14.5。11.6はnで割った分散。"},{"id":"yoso-02","field":"データの基礎","question":"年収のように右に裾の長い(右に歪んだ)分布について、平均値と中央値の関係として最も適切なものはどれか。","choices":["平均値は中央値より大きくなりやすい","平均値は中央値より小さくなりやすい","平均値と中央値は常に一致する","平均値は最頻値より必ず小さい"],"answer":1,"explanation":"大きな値に引っ張られ、平均値は中央値より大きくなりやすい。"},{"id":"yoso-03","field":"データの基礎","question":"集団Aは平均200・標準偏差30、集団Bは平均50・標準偏差10である。相対的なばらつきについて正しいものはどれか。","choices":["標準偏差が大きいAの方が相対的ばらつきも大きい","変動係数はBの方が大きい","変動係数は両者で等しい","平均が異なるため比較できない"],"answer":2,"explanation":"変動係数=標準偏差/平均。A=0.15、B=0.2でBの方が大きい。"},{"id":"yoso-04","field":"2変数・時系列","question":"xとyの標本共分散が12、xの標準偏差が4、yの標準偏差が5のとき、相関係数はいくつか。","choices":["0.24","0.6","2.4","0.15"],"answer":2,"explanation":"r=共分散/(sx×sy)=12/20=0.6。"},{"id":"yoso-05","field":"2変数・時系列","question":"時系列 10, 14, 12, 18, 16 (第1〜5期)の、第3期を中心とする3項移動平均はいくつか。","choices":["12.0","14.0","14.67","15.33"],"answer":3,"explanation":"第2〜4期の平均=(14+12+18)/3=44/3≈14.67。"},{"id":"yoso-06","field":"2変数・時系列","question":"基準時点の価格・数量が A:100円・10個、B:200円・5個、比較時点の価格が A:120円、B:220円のとき、ラスパイレス価格指数(基準=100)はいくつか。","choices":["110","115","120","230"],"answer":2,"explanation":"基準時点の数量で加重。Σpt·q0=1200+1100=2300、Σp0·q0=1000+1000=2000。2300/2000×100=115。"},{"id":"yoso-07","field":"確率","question":"事象A, Bについて P(A)=0.4, P(B)=0.5, P(A∩B)=0.2 のとき、正しいものはどれか。","choices":["AとBは排反である","AとBは独立である","P(A∪B)=0.9 である","P(A|B)=0.2 である"],"answer":2,"explanation":"P(A)P(B)=0.2=P(A∩B)なので独立。P(A∪B)=0.7、P(A|B)=0.2/0.5=0.4。"},{"id":"yoso-08","field":"確率","question":"ある病気の有病率は10%。検査の感度(病気の人が陽性)は80%、病気でない人が陽性となる確率は10%である。陽性だった人が実際に病気である確率に最も近いものはどれか。","choices":["0.08","0.47","0.80","0.90"],"answer":2,"explanation":"P(陽性)=0.1×0.8+0.9×0.1=0.17。P(病気|陽性)=0.08/0.17≈0.47。"},{"id":"yoso-09","field":"確率","question":"公平なサイコロを2回振る。出た目の和が7になる確率はいくつか。","choices":["1/12","1/9","1/6","7/36"],"answer":3,"explanation":"和が7になるのは6通り(1-6, 2-5, ... 6-1)。6/36=1/6。"},{"id":"yoso-10","field":"確率変数と確率分布","question":"二項分布 B(20, 0.3) に従う確率変数の分散はいくつか。","choices":["4.2","6.0","1.8","2.05"],"answer":1,"explanation":"分散=np(1−p)=20×0.3×0.7=4.2。平均np=6.0。"},{"id":"yoso-11","field":"確率変数と確率分布","question":"確率変数Xの期待値が2、分散が3のとき、Y=4X−1の分散はいくつか。","choices":["11","12","47","48"],"answer":4,"explanation":"V[aX+b]=a²V[X]=16×3=48。定数bは分散に影響しない(期待値は4×2−1=7)。"},{"id":"yoso-12","field":"確率変数と確率分布","question":"公平なサイコロの出る目Xの分散に最も近いものはどれか。","choices":["2.50","2.92","3.50","15.17"],"answer":2,"explanation":"E[X]=3.5、E[X²]=91/6≈15.17。V=E[X²]−(E[X])²=35/12≈2.92。"},{"id":"yoso-13","field":"正規分布と標本分布","question":"Xが正規分布 N(100, 15²) に従うとき、X≥130となる確率に最も近いものはどれか。","choices":["約0.15%","約2.5%","約5%","約16%"],"answer":2,"explanation":"130は平均+2標準偏差。±2σに約95%が入るので、片側の上側確率は約2.5%。"},{"id":"yoso-14","field":"正規分布と標本分布","question":"母標準偏差12の母集団から大きさ36の無作為標本を取る。標本平均の標準誤差はいくつか。","choices":["0.33","2","6","12"],"answer":2,"explanation":"標準誤差=σ/√n=12/6=2。"},{"id":"yoso-15","field":"正規分布と標本分布","question":"中心極限定理の説明として最も適切なものはどれか。","choices":["母分散が有限なら、標本サイズが大きいとき標本平均の分布は正規分布に近づく","標本サイズが大きいと、個々のデータが正規分布に従うようになる","標本サイズが大きいほど標本平均の分散は大きくなる","標本平均は常に母平均と一致する"],"answer":1,"explanation":"母集団の分布の形によらず、標本平均の分布が正規分布に近づくという定理。"},{"id":"yoso-16","field":"統計的推定","question":"母標準偏差10が既知の母集団から、大きさ25の標本を取ったところ標本平均が50だった。母平均の95%信頼区間(z=1.96)はどれか。","choices":["[46.08, 53.92]","[48.04, 51.96]","[40.2, 59.8]","[49.02, 50.98]"],"answer":1,"explanation":"標準誤差=10/5=2。50±1.96×2=50±3.92。"},{"id":"yoso-17","field":"統計的推定","question":"他の条件を変えず、標本サイズを4倍にしたとき、母平均の信頼区間の幅はおよそ何倍になるか。","choices":["1/4倍","1/2倍","2倍","変わらない"],"answer":2,"explanation":"区間幅は標準誤差∝1/√nに比例。√4=2なので1/2倍。"},{"id":"yoso-18","field":"統計的推定","question":"母集団をいくつかの層に分け、各層から無作為に標本を抽出する方法はどれか。","choices":["単純無作為抽出","層化抽出","クラスター抽出","系統抽出"],"answer":2,"explanation":"層化抽出。クラスター抽出は集団(クラスター)単位で無作為に選ぶ方法。"},{"id":"yoso-19","field":"仮説検定","question":"第1種の過誤の説明として正しいものはどれか。","choices":["帰無仮説が真なのに棄却してしまう誤り","帰無仮説が偽なのに棄却しない誤り","P値が有意水準を超えること","検出力のこと"],"answer":1,"explanation":"第1種の過誤の確率が有意水準。「帰無仮説が偽なのに棄却しない誤り」は第2種の過誤。"},{"id":"yoso-20","field":"仮説検定","question":"H0: μ=50 vs H1: μ≠50 を、母標準偏差10が既知、n=100、標本平均52、有意水準5%(臨界値±1.96)で検定する。検定統計量と結論の組合せとして正しいものはどれか。","choices":["z=0.2、棄却されない","z=2.0、棄却される","z=2.0、棄却されない","z=0.2、棄却される"],"answer":2,"explanation":"z=(52−50)/(10/√100)=2.0。|z|>1.96なのでH0は棄却される。"},{"id":"yoso-21","field":"仮説検定","question":"検定のP値が0.03であった。結論として正しいものはどれか。","choices":["有意水準5%でも1%でも棄却される","有意水準5%では棄却され、1%では棄却されない","有意水準5%では棄却されず、1%では棄却される","どちらの有意水準でも棄却されない"],"answer":2,"explanation":"P値≦有意水準なら棄却。0.03≦0.05、0.03>0.01。"},{"id":"yoso-22","field":"回帰分析と分散分析","question":"単回帰で、xの平均が5、yの平均が20、回帰係数(傾き)が2のとき、回帰直線の切片はいくつか。","choices":["8","10","15","30"],"answer":2,"explanation":"回帰直線は(x̄, ȳ)を通る。a=ȳ−b·x̄=20−2×5=10。"},{"id":"yoso-23","field":"回帰分析と分散分析","question":"総平方和が200、残差平方和が50の回帰分析の決定係数R²はいくつか。","choices":["0.25","0.50","0.75","0.80"],"answer":3,"explanation":"R²=1−残差平方和/総平方和=1−50/200=0.75。"},{"id":"yoso-24","field":"回帰分析と分散分析","question":"3水準、各水準5個(計15個)の一元配置分散分析で、F統計量の自由度(水準間, 残差)はどれか。","choices":["(2, 14)","(2, 12)","(3, 12)","(3, 15)"],"answer":2,"explanation":"水準間の自由度=3−1=2、残差の自由度=15−3=12。"},{"id":"yoso-25","field":"データの基礎","question":"次のうち、間隔尺度に分類されるものはどれか。","choices":["血液型","成績の順位","摂氏の気温","体重"],"answer":3,"explanation":"摂氏は0が「無」を意味せず、差に意味がある間隔尺度。体重は比例尺度、順位は順序尺度、血液型は名義尺度。"},{"id":"yoso-26","field":"データの基礎","question":"平均60、標準偏差15の試験で得点が75の人の偏差値はいくつか。","choices":["55","60","65","75"],"answer":2,"explanation":"偏差値=50+10×(75−60)/15=60。"},{"id":"yoso-27","field":"データの基礎","question":"データ 2, 3, 4, 5, 100 について、外れ値の影響を最も受けにくい代表値はどれか。","choices":["平均値","中央値","分散","範囲"],"answer":2,"explanation":"平均値は22.8と外れ値に引っ張られるが、中央値は4のまま。"},{"id":"yoso-28","field":"2変数・時系列","question":"xとyの相関係数がrのとき、y を y'=3y+1 に変換した後のxとy'の相関係数はどうなるか。","choices":["3倍になる","3r+1になる","変わらない","符号が反転する"],"answer":3,"explanation":"正の係数による1次変換では相関係数は変わらない。"},{"id":"yoso-29","field":"2変数・時系列","question":"アイスクリームの売上と水難事故件数に強い正の相関がみられた。最も適切な解釈はどれか。","choices":["アイスの消費が事故を引き起こす","事故が増えるとアイスが売れる","気温など第三の変数による擬似相関の可能性がある","相関があるので因果関係が証明された"],"answer":3,"explanation":"気温の上昇が両方を増やす交絡が考えられる。相関だけでは因果は示せない。"},{"id":"yoso-30","field":"2変数・時系列","question":"売上が第1期100、第2期120、第3期150であった。第1期に対する第3期の増加率はいくつか。","choices":["45%","50%","22.5%","225%"],"answer":2,"explanation":"150/100=1.5なので50%増。前期比(20%と25%)の単純和45%は誤り。"},{"id":"yoso-31","field":"確率","question":"P(A)=0.5、P(B)=0.3、P(A∪B)=0.6のとき、P(A∩B)はいくつか。","choices":["0.1","0.2","0.15","0.8"],"answer":2,"explanation":"加法定理 P(A∪B)=P(A)+P(B)−P(A∩B) より 0.5+0.3−0.6=0.2。"},{"id":"yoso-32","field":"確率","question":"コインを3回投げるとき、少なくとも1回表が出る確率はいくつか。","choices":["1/8","3/8","7/8","1/2"],"answer":3,"explanation":"余事象(すべて裏)の確率は1/8。1−1/8=7/8。"},{"id":"yoso-33","field":"確率","question":"赤玉3個、白玉2個の袋から、戻さずに2個取り出す。2個とも赤玉である確率はいくつか。","choices":["9/25","3/10","2/5","3/5"],"answer":2,"explanation":"3/5×2/4=3/10。戻す場合の9/25とは異なる。"},{"id":"yoso-34","field":"確率変数と確率分布","question":"確率変数Xが値0, 1, 2をそれぞれ確率0.2, 0.5, 0.3でとるとき、E[X]はいくつか。","choices":["1.0","1.1","1.2","1.5"],"answer":2,"explanation":"0×0.2+1×0.5+2×0.3=1.1。"},{"id":"yoso-35","field":"確率変数と確率分布","question":"XとYが独立で、V[X]=4、V[Y]=9のとき、V[X−Y]はいくつか。","choices":["5","13","25","36"],"answer":2,"explanation":"独立なら V[X−Y]=V[X]+V[Y]=13。引き算でも分散は足す。"},{"id":"yoso-36","field":"確率変数と確率分布","question":"成功確率p=0.25の試行を、初めて成功するまで繰り返す。試行回数の期待値はいくつか(幾何分布)。","choices":["0.25","3","4","16"],"answer":3,"explanation":"幾何分布の期待値は1/p=4。"},{"id":"yoso-37","field":"正規分布と標本分布","question":"XとYが独立で、X〜N(10, 4)、Y〜N(20, 9)(N(平均, 分散))のとき、X+Yの分布はどれか。","choices":["N(30, 13)","N(30, 25)","N(30, 5)","N(15, 13)"],"answer":1,"explanation":"正規分布の再生性。平均は10+20=30、分散は独立なので4+9=13。"},{"id":"yoso-38","field":"正規分布と標本分布","question":"X〜N(50, 16)(平均50、分散16)のとき、P(X≧54)に最も近い値はどれか。","choices":["0.02","0.16","0.34","0.84"],"answer":2,"explanation":"標準偏差4。54は+1σなので、標準化してP(Z≧1)≈0.16。"},{"id":"yoso-39","field":"正規分布と標本分布","question":"正規母集団から大きさ16の標本をとり、母分散が未知のとき、標本平均を標準化した統計量(標本の不偏分散を用いる)はどの分布に従うか。","choices":["自由度16のt分布","自由度15のt分布","自由度15のχ²分布","標準正規分布"],"answer":2,"explanation":"T=(X̄−μ)/(s/√n)は自由度n−1=15のt分布に従う。"},{"id":"yoso-40","field":"統計的推定","question":"n=400の標本で標本比率が0.5のとき、母比率の95%信頼区間(z=1.96、標本比率で近似)はどれか。","choices":["[0.451, 0.549]","[0.402, 0.598]","[0.475, 0.525]","[0.49, 0.51]"],"answer":1,"explanation":"標準誤差=√(0.5×0.5/400)=0.025。0.5±1.96×0.025=0.5±0.049。"},{"id":"yoso-41","field":"統計的推定","question":"「母平均の95%信頼区間」の解釈として最も適切なものはどれか。","choices":["同じ方法で何度も区間を作ると、約95%の区間が母平均を含む","計算された1つの区間に、母平均が95%の確率で含まれる","標本の95%がこの区間に入る","母平均が95%の確率でこの区間内を動く"],"answer":1,"explanation":"母平均は定数。確率は区間を作る手続きに対するもの。"},{"id":"yoso-42","field":"統計的推定","question":"不偏推定量についての記述として正しいものはどれか。","choices":["標本平均の期待値は母平均に等しい","nで割る標本分散は母分散の不偏推定量である","標本サイズが大きければどんな推定量も不偏になる","標本中央値は常に母平均の不偏推定量である"],"answer":1,"explanation":"E[X̄]=μ。母分散の不偏推定量はn−1で割る不偏分散。"},{"id":"yoso-43","field":"仮説検定","question":"正規母集団(母分散既知)で、H1:μ>μ0 の片側検定を有意水準5%で行うときの臨界値はどれか。","choices":["1.282","1.645","1.96","2.576"],"answer":2,"explanation":"上側5%点は1.645。1.96は両側5%の臨界値。"},{"id":"yoso-44","field":"仮説検定","question":"検定の検出力を高める方法として適切なものはどれか。","choices":["標本サイズを大きくする","有意水準を小さくする","母分散が大きい対象を選ぶ","帰無仮説と真の値の差が小さい状況で検定する"],"answer":1,"explanation":"標本サイズを増やすと標準誤差が小さくなり、検出力(1−β)が上がる。他は検出力を下げる方向。"},{"id":"yoso-45","field":"仮説検定","question":"H0:p=0.5の母比率の検定で、n=100、標本比率が0.6のとき、検定統計量zはいくつか。","choices":["1.0","2.0","4.0","0.2"],"answer":2,"explanation":"z=(0.6−0.5)/√(0.5×0.5/100)=0.1/0.05=2.0。"},{"id":"yoso-46","field":"回帰分析と分散分析","question":"xとyの相関係数が0.6、xの標準偏差が5、yの標準偏差が10のとき、yをxに回帰したときの傾きはいくつか。","choices":["0.3","1.2","3.0","0.6"],"answer":2,"explanation":"b=r×(sy/sx)=0.6×10/5=1.2。"},{"id":"yoso-47","field":"回帰分析と分散分析","question":"n=12の観測値による単回帰分析で、残差平方和の自由度はいくつか。","choices":["9","10","11","12"],"answer":2,"explanation":"n−2=10(切片と傾きの2つを推定)。"},{"id":"yoso-48","field":"回帰分析と分散分析","question":"重回帰分析における多重共線性の説明として適切なものはどれか。","choices":["説明変数同士の相関が非常に強く、偏回帰係数の推定が不安定になる","残差の分散が説明変数の値によって変わる","目的変数が正規分布に従わない","目的変数と残差の相関が強い"],"answer":1,"explanation":"説明変数間の強い相関により係数の標準誤差が大きくなる。「残差の分散が説明変数の値によって変わる」は不均一分散の説明。"},{"id":"yoso-49","field":"データの基礎","question":"データ 1, 3, 5, 7, 9, 11, 13, 15 の四分位範囲はいくつか(データを下位半分と上位半分に分け、それぞれの中央値を第1・第3四分位数とする)。","choices":["6","7","8","14"],"answer":3,"explanation":"第1四分位数=(3+5)/2=4、第3四分位数=(11+13)/2=12。差は8。"},{"id":"yoso-50","field":"データの基礎","question":"度数分布表で、階級0〜10の度数が4、階級10〜20の度数が6のとき、階級値を用いた平均はいくつか。","choices":["10","11","12","15"],"answer":2,"explanation":"階級値は5と15。(5×4+15×6)/10=11。"},{"id":"yoso-51","field":"データの基礎","question":"データxの分散が9のとき、y=2x+5の標準偏差はいくつか。","choices":["6","9","11","18"],"answer":1,"explanation":"xの標準偏差は3。標準偏差は|a|倍されるので2×3=6。定数5は影響しない。"},{"id":"yoso-52","field":"2変数・時系列","question":"散布図上のすべての点が右下がりの一直線上に並んでいるとき、相関係数はいくつか。","choices":["−1","0","1","定まらない"],"answer":1,"explanation":"完全な負の線形関係なのでr=−1。"},{"id":"yoso-53","field":"2変数・時系列","question":"時系列データの変動のうち、1年を周期として繰り返される変動はどれか。","choices":["傾向変動","季節変動","循環変動","不規則変動"],"answer":2,"explanation":"1年周期の規則的な変動が季節変動。循環変動は数年にわたる周期。"},{"id":"yoso-54","field":"2変数・時系列","question":"基準時点の価格が A:100円・B:200円、比較時点の価格が A:120円・B:220円、比較時点の数量が A:8個・B:6個のとき、パーシェ価格指数(基準=100)はいくつか。","choices":["110","114","115","120"],"answer":2,"explanation":"比較時点の数量で加重。Σpt·qt=960+1320=2280、Σp0·qt=800+1200=2000。2280/2000×100=114。"},{"id":"yoso-55","field":"確率","question":"事象A, Bが排反で、P(A)=0.3、P(B)=0.4のとき、P(A∪B)はいくつか。","choices":["0.12","0.58","0.7","0.1"],"answer":3,"explanation":"排反ならP(A∩B)=0なので、P(A∪B)=0.3+0.4=0.7。"},{"id":"yoso-56","field":"確率","question":"ある製品の60%を工場A(不良率2%)、40%を工場B(不良率5%)で作っている。不良品だったとき、それが工場Aの製品である確率はいくつか。","choices":["0.375","0.6","0.02","0.625"],"answer":1,"explanation":"P(不良)=0.6×0.02+0.4×0.05=0.032。P(A|不良)=0.012/0.032=0.375。"},{"id":"yoso-57","field":"確率","question":"5人の中から委員2人を選ぶ方法は何通りか(順序は考えない)。","choices":["5","10","20","25"],"answer":2,"explanation":"5C2=5×4/2=10。"},{"id":"yoso-58","field":"確率変数と確率分布","question":"V[X]=4、V[Y]=9、Cov(X,Y)=2のとき、V[X+Y]はいくつか。","choices":["13","15","17","19"],"answer":3,"explanation":"V[X+Y]=V[X]+V[Y]+2Cov=4+9+4=17。"},{"id":"yoso-59","field":"確率変数と確率分布","question":"平均2のポアソン分布に従う確率変数Xについて、P(X=0)に最も近い値はどれか。","choices":["0.135","0.271","0.368","0.865"],"answer":1,"explanation":"P(X=0)=e^(−2)≈0.135。0.368はe^(−1)。"},{"id":"yoso-60","field":"確率変数と確率分布","question":"区間[0, 10]上の連続一様分布に従う確率変数の分散はいくつか。","choices":["2.5","5","8.33","10"],"answer":3,"explanation":"一様分布の分散は(b−a)²/12=100/12≈8.33。"},{"id":"yoso-61","field":"正規分布と標本分布","question":"母分散36の母集団から大きさ9の無作為標本を取るとき、標本平均の分散はいくつか。","choices":["4","2","6","36"],"answer":1,"explanation":"V[X̄]=σ²/n=36/9=4。"},{"id":"yoso-62","field":"正規分布と標本分布","question":"正規分布 N(μ, σ²) に従う確率変数が μ±3σ の範囲に入る確率に最も近いものはどれか。","choices":["約68%","約95%","約99.7%","約50%"],"answer":3,"explanation":"±1σで約68%、±2σで約95%、±3σで約99.7%。"},{"id":"yoso-63","field":"正規分布と標本分布","question":"Z1, …, Z4が独立に標準正規分布に従うとき、Z1²+…+Z4² の期待値はいくつか。","choices":["1","2","4","8"],"answer":3,"explanation":"自由度4のχ²分布で、平均は自由度に等しい。"},{"id":"yoso-64","field":"統計的推定","question":"母比率を95%信頼で誤差±0.05以内に推定したい。母比率の見当がつかない(p=0.5とみなす)とき、必要な最小の標本サイズに最も近いものはどれか(z=1.96)。","choices":["196","385","1537","3074"],"answer":2,"explanation":"n≥(1.96/0.05)²×0.25=384.16。切り上げて385。"},{"id":"yoso-65","field":"統計的推定","question":"正規母集団から n=9 の標本を取り、標本平均20、標本標準偏差6だった。母平均の95%信頼区間はどれか(自由度8のt分布の上側2.5%点は2.306)。","choices":["[15.39, 24.61]","[16.08, 23.92]","[6.16, 33.84]","[18.0, 22.0]"],"answer":1,"explanation":"標準誤差=6/3=2。20±2.306×2=20±4.612。"},{"id":"yoso-66","field":"統計的推定","question":"フィッシャーの3原則に含まれないものはどれか。","choices":["無作為化","反復","局所管理","二重盲検化"],"answer":4,"explanation":"3原則は無作為化・反復・局所管理。二重盲検化は含まれない。"},{"id":"yoso-67","field":"仮説検定","question":"H0:μ=100の検定で、n=16、標本平均105、標本標準偏差8のとき、t統計量はいくつか。","choices":["0.625","1.25","2.5","5.0"],"answer":3,"explanation":"t=(105−100)/(8/√16)=5/2=2.5(自由度15)。"},{"id":"yoso-68","field":"仮説検定","question":"他の条件を変えずに有意水準を5%から1%に下げると、第2種の過誤の確率は一般にどうなるか。","choices":["大きくなる","小さくなる","変わらない","0になる"],"answer":1,"explanation":"第1種の過誤を減らすと棄却しにくくなり、第2種の過誤は増える(トレードオフ)。"},{"id":"yoso-69","field":"仮説検定","question":"3行4列の分割表に対する独立性のカイ二乗検定の自由度はいくつか。","choices":["6","7","11","12"],"answer":1,"explanation":"(行数−1)(列数−1)=2×3=6。"},{"id":"yoso-70","field":"回帰分析と分散分析","question":"回帰直線 y=10+2x で、x=3の観測値がy=18のとき、残差(観測値−予測値)はいくつか。","choices":["−2","2","16","18"],"answer":2,"explanation":"予測値=10+6=16。残差=18−16=2。"},{"id":"yoso-71","field":"回帰分析と分散分析","question":"一元配置分散分析で、群間平方和60(自由度2)、群内平方和120(自由度12)のとき、F値はいくつか。","choices":["0.5","3.0","6.0","1.5"],"answer":2,"explanation":"F=(60/2)/(120/12)=30/10=3.0。"},{"id":"yoso-72","field":"回帰分析と分散分析","question":"単回帰で、傾きの推定値が1.5、その標準誤差が0.5のとき、H0:傾き=0に対するt統計量はいくつか。","choices":["0.33","3.0","0.75","1.5"],"answer":2,"explanation":"t=1.5/0.5=3.0(自由度はn−2)。"},{"id":"yoso-73","field":"データの基礎","question":"5人の試験の平均点が60点であった。得点90点の1人を加えた6人の平均点はいくつか。","choices":["62.5","65","70","75"],"answer":2,"explanation":"合計は5×60=300。(300+90)/6=65。"},{"id":"yoso-74","field":"データの基礎","question":"所得分布がすべての人で完全に等しいとき、ジニ係数はいくつか。","choices":["0","0.5","1","定まらない"],"answer":1,"explanation":"完全平等ではローレンツ曲線が均等分布線に一致し、ジニ係数は0。"},{"id":"yoso-75","field":"データの基礎","question":"データ 7, 1, 9, 4, 5, 8 の中央値はいくつか。","choices":["5","6","6.5","7"],"answer":2,"explanation":"並べると1,4,5,7,8,9。n=6は偶数なので中央の2つ(5と7)の平均6。"},{"id":"yoso-76","field":"2変数・時系列","question":"(x, y)=(1,2), (2,4), (3,6)の3組のデータの共分散(nで割る)はいくつか。","choices":["1.33","2","4","0.67"],"answer":1,"explanation":"x̄=2、ȳ=4。偏差積の和=2+0+2=4。n=3で割って4/3≈1.33。"},{"id":"yoso-77","field":"2変数・時系列","question":"ラスパイレス指数が115、パーシェ指数が114のとき、フィッシャー指数に最も近い値はどれか。","choices":["114.0","114.5","115.0","229"],"answer":2,"explanation":"フィッシャー指数はラスパイレスとパーシェの幾何平均。√(115×114)=√13110≈114.5。"},{"id":"yoso-78","field":"2変数・時系列","question":"月次データに年周期の季節変動があるとき、自己相関(コレログラム)について最も適切なものはどれか。","choices":["ラグ6で最大の正の値になる","ラグ12で大きな正の自己相関が現れやすい","ラグ1の自己相関は常に0になる","自己相関は−1〜1の範囲を超えることがある"],"answer":2,"explanation":"12か月周期で似た値が繰り返されるため、ラグ12で正の自己相関が大きくなる。自己相関は−1〜1の範囲。"},{"id":"yoso-79","field":"確率","question":"成功確率0.2の試行を独立に3回行う。3回とも成功する確率はいくつか。","choices":["0.6","0.008","0.08","0.2"],"answer":2,"explanation":"独立なので0.2³=0.008。"},{"id":"yoso-80","field":"確率","question":"P(A∩B)=0.12、P(B)=0.3のとき、条件付き確率P(A|B)はいくつか。","choices":["0.04","0.36","0.4","2.5"],"answer":3,"explanation":"P(A|B)=P(A∩B)/P(B)=0.12/0.3=0.4。"},{"id":"yoso-81","field":"確率","question":"公平なサイコロを2回振るとき、少なくとも1回6の目が出る確率はいくつか。","choices":["1/6","11/36","1/3","5/36"],"answer":2,"explanation":"余事象(どちらも6以外)は25/36。1−25/36=11/36。"},{"id":"yoso-82","field":"確率変数と確率分布","question":"二項分布B(3, 0.5)に従う確率変数Xについて、P(X=2)はいくつか。","choices":["0.25","0.375","0.5","0.75"],"answer":2,"explanation":"3C2×0.5²×0.5=3×0.125=0.375。"},{"id":"yoso-83","field":"確率変数と確率分布","question":"E[X]=3、V[X]=4のとき、E[X²]はいくつか。","choices":["7","9","13","16"],"answer":3,"explanation":"E[X²]=V[X]+(E[X])²=4+9=13。"},{"id":"yoso-84","field":"確率変数と確率分布","question":"XとYが独立で、E[X]=2、E[Y]=5のとき、E[XY]はいくつか。","choices":["7","10","3","定まらない"],"answer":2,"explanation":"独立ならE[XY]=E[X]E[Y]=10。"},{"id":"yoso-85","field":"正規分布と標本分布","question":"標準正規分布に従うZについて、P(|Z|>1.96)に最も近い値はどれか。","choices":["0.025","0.05","0.10","0.95"],"answer":2,"explanation":"P(|Z|≦1.96)≈0.95なので、残りの両側合計は0.05。"},{"id":"yoso-86","field":"正規分布と標本分布","question":"母比率0.4の母集団から大きさ100の標本を取るとき、標本比率の標準偏差に最も近い値はどれか。","choices":["0.024","0.049","0.24","0.4"],"answer":2,"explanation":"√(0.4×0.6/100)=√0.0024≈0.049。"},{"id":"yoso-87","field":"正規分布と標本分布","question":"標準正規分布に従うZについて、P(Z≧1.5)=0.0668である。P(−1.5≦Z≦1.5)に最も近い値はどれか。","choices":["0.8664","0.9332","0.0668","0.1336"],"answer":1,"explanation":"対称性より両側の確率は2×0.0668=0.1336。1−0.1336=0.8664。"},{"id":"yoso-88","field":"統計的推定","question":"他の条件が同じとき、母平均の99%信頼区間の幅は95%信頼区間の幅と比べてどうなるか。","choices":["狭くなる","広くなる","同じ","標本によって異なる"],"answer":2,"explanation":"信頼係数を上げるとz値が大きくなる(2.576>1.96)ため、区間は広くなる。"},{"id":"yoso-89","field":"統計的推定","question":"標本サイズが大きくなるにつれ、推定量が母数に確率収束する性質を何というか。","choices":["不偏性","一致性","有効性","十分性"],"answer":2,"explanation":"一致性。不偏性は期待値が母数に等しい性質。"},{"id":"yoso-90","field":"統計的推定","question":"n=100の標本で標本比率が0.3のとき、標本比率の標準誤差の推定値に最も近いものはどれか。","choices":["0.021","0.046","0.21","0.3"],"answer":2,"explanation":"√(0.3×0.7/100)=√0.0021≈0.046。"},{"id":"yoso-91","field":"仮説検定","question":"正規分布を用いた両側検定で、有意水準1%の臨界値はどれか。","choices":["1.645","1.96","2.326","2.576"],"answer":4,"explanation":"両側1%は上側0.5%点で2.576。2.326は片側1%点。"},{"id":"yoso-92","field":"仮説検定","question":"サイコロを60回振り、1〜6の目の観測度数が8, 12, 10, 9, 11, 10であった。「公平なサイコロ」の適合度検定のχ²統計量はいくつか。","choices":["0.1","1.0","10.0","6.0"],"answer":2,"explanation":"期待度数は各10。Σ(観測−期待)²/期待=(4+4+0+1+1+0)/10=1.0。"},{"id":"yoso-93","field":"仮説検定","question":"同じ被験者10人の、投薬前後の血圧を比較したい。最も適切な検定はどれか。","choices":["対応のある2標本のt検定","独立な2標本のt検定","適合度のカイ二乗検定","分散比のF検定"],"answer":1,"explanation":"同一対象の前後比較なので、差を1つの標本とみなす対応のあるt検定。"},{"id":"yoso-94","field":"回帰分析と分散分析","question":"単回帰で決定係数R²=0.64、回帰直線の傾きが正のとき、相関係数はいくつか。","choices":["0.32","0.64","0.8","−0.8"],"answer":3,"explanation":"R²=r²。傾きが正なのでr=+0.8。"},{"id":"yoso-95","field":"回帰分析と分散分析","question":"最小二乗法で最小化されるものはどれか。","choices":["残差の絶対値の和","残差の2乗和","説明変数の分散","目的変数と平均との差の和"],"answer":2,"explanation":"最小二乗法は残差平方和を最小にする。"},{"id":"yoso-96","field":"回帰分析と分散分析","question":"一元配置分散分析で、群間平方和が60、群内(残差)平方和が120のとき、総平方和はいくつか。","choices":["60","120","180","7200"],"answer":3,"explanation":"総平方和=群間+群内=180。"},{"id":"yoso-97","field":"データの基礎","question":"箱ひげ図で、第1四分位数が10、第3四分位数が20のとき、「Q3+1.5×四分位範囲」で決まるひげの上側の基準値はいくつか。","choices":["30","35","45","50"],"answer":2,"explanation":"四分位範囲=10。Q3+1.5×10=35。これを超える値を外れ値とみなすのが一般的。"},{"id":"yoso-98","field":"データの基礎","question":"階級の度数が順に5, 10, 15, 20(計50)であるとき、第3階級までの累積相対度数はいくつか。","choices":["0.3","0.5","0.6","0.75"],"answer":3,"explanation":"第3階級までの累積度数は30。30/50=0.6。"},{"id":"yoso-99","field":"データの基礎","question":"平均170、標準偏差6の身長の分布で、身長182の人の標準化得点(z)はいくつか。","choices":["1","2","12","6"],"answer":2,"explanation":"z=(182−170)/6=2。"},{"id":"yoso-100","field":"2変数・時系列","question":"名目の売上が530、デフレーター(基準年=100)が106のとき、実質の売上はいくつか。","choices":["500","530","562","106"],"answer":1,"explanation":"実質値=名目値/(デフレーター/100)=530/1.06=500。"},{"id":"yoso-101","field":"2変数・時系列","question":"月次の売上を「前年同月比」で比べる主な目的として最も適切なものはどれか。","choices":["季節変動の影響を除いて傾向を見る","外れ値を除去する","平均値を求める","分散を小さくする"],"answer":1,"explanation":"同じ月どうしを比べると、季節変動の影響がほぼ相殺される。"},{"id":"yoso-102","field":"2変数・時系列","question":"全体のデータでは正の相関が見られたが、2つの層に分けると各層では負の相関になった。この現象の説明として最も適切なものはどれか。","choices":["計算ミスが必ずある","異なる集団が混在していることによる見かけの相関(シンプソンのパラドックス)の可能性がある","外れ値のみが原因である","相関係数は層別しても必ず同じになる"],"answer":2,"explanation":"層(集団)の違いが交絡となり、全体と層別で相関の向きが逆転することがある。"},{"id":"yoso-103","field":"確率","question":"5人から3人を選び、順番をつけて並べる方法は何通りか。","choices":["10","30","60","125"],"answer":3,"explanation":"5P3=5×4×3=60。順序を考えない5C3=10とは異なる。"},{"id":"yoso-104","field":"確率","question":"P(A)=0.5、P(B|A)=0.4のとき、P(A∩B)はいくつか。","choices":["0.2","0.45","0.9","0.8"],"answer":1,"explanation":"乗法定理 P(A∩B)=P(A)P(B|A)=0.5×0.4=0.2。"},{"id":"yoso-105","field":"確率","question":"P(A)>0、P(B)>0で、事象AとBが排反であるとき、AとBの独立性について正しいものはどれか。","choices":["常に独立である","独立にはならない","条件により独立になる","必ず独立かつ同値である"],"answer":2,"explanation":"排反ならP(A∩B)=0だが、P(A)P(B)>0なのでP(A∩B)≠P(A)P(B)。独立ではない。"},{"id":"yoso-106","field":"確率変数と確率分布","question":"確率変数Xが P(X=1)=k、P(X=2)=2k、P(X=3)=3k に従うとき、E[X]はいくつか。","choices":["2.0","7/3","2.5","3.0"],"answer":2,"explanation":"総和が1なので6k=1、k=1/6。E[X]=(1+4+9)/6=14/6=7/3。"},{"id":"yoso-107","field":"確率変数と確率分布","question":"平均4のポアソン分布に従う確率変数の分散はいくつか。","choices":["2","4","16","8"],"answer":2,"explanation":"ポアソン分布は平均と分散がともにλに等しい。"},{"id":"yoso-108","field":"確率変数と確率分布","question":"二項分布B(100, 0.5)を正規分布で近似するとき、近似する正規分布 N(平均, 分散) はどれか。","choices":["N(50, 5)","N(50, 25)","N(100, 50)","N(0.5, 25)"],"answer":2,"explanation":"平均np=50、分散np(1−p)=25。"},{"id":"yoso-109","field":"正規分布と標本分布","question":"正規母集団から大きさ11の標本を取り、不偏分散をs²とするとき、(n−1)s²/σ²は自由度いくつのカイ二乗分布に従うか。","choices":["9","10","11","1"],"answer":2,"explanation":"自由度はn−1=10。"},{"id":"yoso-110","field":"正規分布と標本分布","question":"独立な確率変数U〜χ²(3)、V〜χ²(8)について、(U/3)/(V/8) が従う分布はどれか。","choices":["F(3, 8)","F(8, 3)","t(8)","χ²(11)"],"answer":1,"explanation":"F分布は(分子の自由度, 分母の自由度)の順。F(3, 8)。"},{"id":"yoso-111","field":"正規分布と標本分布","question":"母集団がN(50, 100)(分散100)のとき、大きさ25の標本平均X̄について、P(X̄≧54)に最も近い値はどれか。","choices":["0.023","0.16","0.05","0.5"],"answer":1,"explanation":"標準誤差=10/5=2。z=(54−50)/2=2。P(Z≧2)≈0.023。"},{"id":"yoso-112","field":"統計的推定","question":"名簿から最初の1人をランダムに選び、以後一定の間隔で標本を抽出する方法はどれか。","choices":["層化抽出","クラスター抽出","系統抽出","多段抽出"],"answer":3,"explanation":"一定間隔で抽出するのが系統抽出。"},{"id":"yoso-113","field":"統計的推定","question":"研究者が対象者を無作為に処置群と対照群に割り当てて比較する研究はどれか。","choices":["観察研究","実験研究","全数調査","悉皆調査"],"answer":2,"explanation":"介入を割り当てる研究は実験研究(ランダム化比較試験など)。"},{"id":"yoso-114","field":"統計的推定","question":"独立な2標本で、母分散25のn=25の標本と、母分散48のn=16の標本の平均の差の標準誤差はいくつか。","choices":["2","4","2.83","1"],"answer":1,"explanation":"√(25/25+48/16)=√(1+3)=2。"},{"id":"yoso-115","field":"仮説検定","question":"母平均μの95%信頼区間が[48, 56]であった。H0:μ=50を有意水準5%の両側検定で検定した結果として正しいものはどれか。","choices":["棄却される","棄却されない","判断できない","片側検定なら必ず棄却される"],"answer":2,"explanation":"50は信頼区間の内側にあるので、両側5%の検定ではH0は棄却されない。"},{"id":"yoso-116","field":"仮説検定","question":"2×2分割表の行合計が50, 50、列合計が40, 60(総計100)のとき、独立性の検定における第1行第1列の期待度数はいくつか。","choices":["20","25","40","50"],"answer":1,"explanation":"期待度数=行合計×列合計/総計=50×40/100=20。"},{"id":"yoso-117","field":"仮説検定","question":"P値の説明として最も適切なものはどれか。","choices":["帰無仮説が真である確率","帰無仮説が真であると仮定したとき、観測された値以上に極端な結果が得られる確率","対立仮説が真である確率","第2種の過誤の確率"],"answer":2,"explanation":"P値は、帰無仮説の下で観測値以上に極端な値が得られる確率。帰無仮説が真である確率ではない。"},{"id":"yoso-118","field":"回帰分析と分散分析","question":"n=30の観測値と説明変数3個の重回帰分析(切片あり)で、残差の自由度はいくつか。","choices":["26","27","28","29"],"answer":1,"explanation":"n−(説明変数の数+1)=30−4=26。"},{"id":"yoso-119","field":"回帰分析と分散分析","question":"回帰分析で、説明変数の観測範囲の外側にある値に対する予測について、最も適切なものはどれか。","choices":["観測範囲内と同じ精度で必ず予測できる","観測範囲外への外挿は信頼性が低くなる可能性がある","観測範囲外のほうが精度は必ず高い","予測はできない"],"answer":2,"explanation":"データのない範囲では関係が同じ形とは限らないので、外挿には注意が必要。"},{"id":"yoso-120","field":"回帰分析と分散分析","question":"一元配置分散分析のF検定における帰無仮説はどれか。","choices":["すべての水準の母平均が等しい","少なくとも1つの水準の母平均が異なる","すべての水準の標本平均が等しい","すべての水準の母分散が異なる"],"answer":1,"explanation":"帰無仮説は「すべての水準の母平均が等しい」。対立仮説が「少なくとも1つ異なる」。"},{"id":"yoso-121","field":"データの基礎","question":"データ 2, 3, 3, 5, 7, 3, 8, 5 の最頻値はいくつか。","choices":["3","4.5","5","8"],"answer":1,"explanation":"最も多く現れる値は3(3回)。平均は36/8=4.5、5は2回。"},{"id":"yoso-122","field":"データの基礎","question":"A組20人の平均点が70点、B組30人の平均点が80点のとき、50人全体の平均点はいくつか。","choices":["75","76","77","78"],"answer":2,"explanation":"加重平均=(20×70+30×80)/50=3800/50=76。単純平均75は誤り。"},{"id":"yoso-123","field":"データの基礎","question":"ローレンツ曲線とジニ係数の関係として正しいものはどれか。","choices":["ジニ係数は、ローレンツ曲線と均等分布線に囲まれた面積の2倍である","ジニ係数は、その面積と等しい","ジニ係数は、その面積の1/2である","ジニ係数は、その面積の4倍である"],"answer":1,"explanation":"均等分布線の下の面積は1/2なので、囲まれた面積を2倍すると0〜1に収まるジニ係数になる。"},{"id":"yoso-124","field":"2変数・時系列","question":"2つの変数の順位が完全に一致するとき、スピアマンの順位相関係数はいくつか。","choices":["−1","0","1","0.5"],"answer":3,"explanation":"順位が完全に一致すると順位相関係数は1。完全に逆順なら−1。"},{"id":"yoso-125","field":"2変数・時系列","question":"ある月の売上の(複数年)平均が120、全月の平均が100のとき、この月の季節指数(全体平均=1)はいくつか。","choices":["0.83","1.2","1.0","12"],"answer":2,"explanation":"季節指数=その月の平均/全体平均=120/100=1.2。"},{"id":"yoso-126","field":"2変数・時系列","question":"相関係数と外れ値に関する記述として最も適切なものはどれか。","choices":["外れ値の影響を受けにくい","1つの外れ値で大きく変わることがある","外れ値があっても必ず変わらない","外れ値があると必ず1になる"],"answer":2,"explanation":"相関係数は平均・分散を使うため外れ値の影響を受けやすい。散布図の確認が重要。"},{"id":"yoso-127","field":"確率","question":"独立な事象A, B, Cの確率がそれぞれ0.5, 0.4, 0.3のとき、少なくとも1つが起こる確率はいくつか。","choices":["0.79","0.21","1.2","0.06"],"answer":1,"explanation":"余事象(どれも起こらない)=0.5×0.6×0.7=0.21。1−0.21=0.79。"},{"id":"yoso-128","field":"確率","question":"箱Xには赤玉3・白玉2、箱Yには赤玉1・白玉4が入っている。箱を等確率で1つ選び、玉を1個取り出すとき、赤玉である確率はいくつか。","choices":["0.2","0.4","0.6","0.8"],"answer":2,"explanation":"全確率の公式。0.5×(3/5)+0.5×(1/5)=0.3+0.1=0.4。"},{"id":"yoso-129","field":"確率","question":"成功確率0.5の試行を独立に5回行う。ちょうど2回成功する確率はいくつか。","choices":["0.25","0.3125","0.4","0.5"],"answer":2,"explanation":"5C2×0.5⁵=10/32=0.3125。"},{"id":"yoso-130","field":"確率変数と確率分布","question":"E[X]=3、E[Y]=5のとき、E[2X−Y+1]はいくつか。","choices":["2","1","7","12"],"answer":1,"explanation":"期待値の線形性。2×3−5+1=2。XとYが独立かどうかは不要。"},{"id":"yoso-131","field":"確率変数と確率分布","question":"Cov(X,Y)=3、V[X]=4、V[Y]=9のとき、XとYの相関係数はいくつか。","choices":["0.5","0.25","0.75","1.5"],"answer":1,"explanation":"ρ=Cov/(√V[X]√V[Y])=3/(2×3)=0.5。"},{"id":"yoso-132","field":"確率変数と確率分布","question":"二項分布B(n, p)に従う確率変数の平均が12、分散が8.4のとき、nはいくつか。","choices":["30","40","50","12"],"answer":2,"explanation":"np=12、np(1−p)=8.4より1−p=0.7、p=0.3。n=12/0.3=40。"},{"id":"yoso-133","field":"正規分布と標本分布","question":"右に裾が長い(右に歪んだ)分布の歪度の符号はどれか。","choices":["正","負","0","定まらない"],"answer":1,"explanation":"右に裾が長いと歪度は正。左に裾が長いと負。"},{"id":"yoso-134","field":"正規分布と標本分布","question":"独立な2つの標本平均X̄1(母分散16、n1=4)とX̄2(母分散36、n2=9)について、X̄1−X̄2の分散はいくつか。","choices":["0","4","8","16"],"answer":3,"explanation":"V[X̄1]=16/4=4、V[X̄2]=36/9=4。独立なので差の分散は和で8。"},{"id":"yoso-135","field":"正規分布と標本分布","question":"X〜N(50, 100)(分散100)のとき、上側2.5%点に最も近い値はどれか。","choices":["60.0","69.6","75.8","79.2"],"answer":2,"explanation":"50+1.96×10=69.6。75.8は上側0.5%点(2.576)。"},{"id":"yoso-136","field":"統計的推定","question":"正規母集団から大きさ11の標本を取り、不偏分散が20であった。母分散の95%信頼区間に最も近いものはどれか(自由度10のχ²分布の上側2.5%点=20.48、下側2.5%点=3.25)。","choices":["[9.77, 61.5]","[3.25, 20.48]","[0.98, 6.15]","[19.5, 40.5]"],"answer":1,"explanation":"(n−1)s²=200。下限=200/20.48≈9.77、上限=200/3.25≈61.5。"},{"id":"yoso-137","field":"統計的推定","question":"都道府県を選び、その中から市町村を選び、さらにその中から世帯を選ぶというように段階的に抽出する方法はどれか。","choices":["層化抽出","多段抽出","系統抽出","単純無作為抽出"],"answer":2,"explanation":"抽出を段階ごとに繰り返す方法が多段抽出。"},{"id":"yoso-138","field":"統計的推定","question":"二項分布で、n=10回中3回成功した。成功確率pの最尤推定値はいくつか。","choices":["0.3","0.5","0.7","3"],"answer":1,"explanation":"尤度を最大にするpは標本比率3/10=0.3。"},{"id":"yoso-139","field":"仮説検定","question":"2標本t検定(等分散を仮定)で、標本1:不偏分散4・n1=5、標本2:不偏分散6・n2=7のとき、プールした分散はいくつか。","choices":["5.0","5.2","5.5","10"],"answer":2,"explanation":"{(n1−1)s1²+(n2−1)s2²}/(n1+n2−2)=(16+36)/10=5.2。"},{"id":"yoso-140","field":"仮説検定","question":"両側検定のP値が0.08で、検定統計量の向きが対立仮説の側にあるとき、対応する片側検定のP値はいくつか。","choices":["0.04","0.08","0.16","0.92"],"answer":1,"explanation":"分布が左右対称なら片側P値は両側P値の半分で0.04。"},{"id":"yoso-141","field":"仮説検定","question":"第2種の過誤の確率が0.2のとき、検出力はいくつか。","choices":["0.2","0.8","0.05","0.95"],"answer":2,"explanation":"検出力=1−第2種の過誤の確率=0.8。"},{"id":"yoso-142","field":"回帰分析と分散分析","question":"重回帰分析のR²と自由度調整済みR²について、正しいものはどれか。","choices":["説明変数を追加してもR²は減らないが、自由度調整済みR²は減ることがある","どちらも説明変数を追加すると必ず増加する","自由度調整済みR²は常にR²より大きい","説明変数を追加するとR²は必ず減少する"],"answer":1,"explanation":"説明変数を増やすとR²は(ほぼ)増えるが、調整済みR²は自由度でペナルティがかかるため減ることがある。"},{"id":"yoso-143","field":"回帰分析と分散分析","question":"3つのカテゴリをもつ質的変数を重回帰分析の説明変数に用いるとき、必要なダミー変数の個数はいくつか。","choices":["1","2","3","4"],"answer":2,"explanation":"基準カテゴリを除いたカテゴリ数−1=2個。"},{"id":"yoso-144","field":"回帰分析と分散分析","question":"回帰分析の残差プロットで、説明変数が大きいほど残差のばらつきが広がっていた。疑われる問題はどれか。","choices":["多重共線性","不均一分散","外れ値のみ","説明変数の欠測"],"answer":2,"explanation":"残差の分散が一定でない不均一分散。等分散の仮定が崩れている。"},{"id":"yoso-145","field":"データの基礎","question":"n個のデータについて、各データから平均値を引いた偏差の合計はいくつか。","choices":["0","1","n","分散"],"answer":1,"explanation":"偏差の総和は常に0。平均値はデータの重心だから。"},{"id":"yoso-146","field":"データの基礎","question":"データxを z=(x−平均)/標準偏差 に変換したとき、zの平均と分散はどうなるか。","choices":["平均0・分散1","平均0・分散2","平均10・分散1","平均1・分散0"],"answer":1,"explanation":"標準化すると平均0・分散1(標準偏差1)になる。"},{"id":"yoso-147","field":"データの基礎","question":"データ 3, 8, 5, 12, 7 の範囲(レンジ)はいくつか。","choices":["7","8","9","12"],"answer":3,"explanation":"範囲=最大値−最小値=12−3=9。"},{"id":"yoso-148","field":"2変数・時系列","question":"2変数の共分散が負の値であるとき、相関係数について正しいものはどれか。","choices":["正の値","負の値","0","1"],"answer":2,"explanation":"相関係数は共分散を標準偏差の積(正)で割るので、共分散と符号が一致する。"},{"id":"yoso-149","field":"2変数・時系列","question":"ある指標が第1期100、第2期110、第3期99であった。第3期の前期比の変化率はいくつか。","choices":["−10%","−9%","−1%","−11%"],"answer":1,"explanation":"99/110=0.9なので前期から10%減少。"},{"id":"yoso-150","field":"2変数・時系列","question":"2変数の相関係数が−0.9であるとき、最も適切な解釈はどれか。","choices":["強い正の相関がある","弱い負の相関がある","強い負の直線的な関係がある","無相関である"],"answer":3,"explanation":"|r|が1に近いので強い関係。符号が負なので負の相関。"},{"id":"yoso-151","field":"確率","question":"100人のうち、英語ができる人が60人、数学ができる人が50人、両方できる人が30人であった。どちらもできない人は何人か。","choices":["10","20","30","40"],"answer":2,"explanation":"英語または数学ができる人=60+50−30=80。100−80=20。"},{"id":"yoso-152","field":"確率","question":"迷惑メールは全体の20%である。迷惑メールの50%、通常メールの5%に「無料」の語が含まれる。「無料」を含むメールが迷惑メールである確率に最も近い値はどれか。","choices":["0.5","0.71","0.1","0.9"],"answer":2,"explanation":"P(無料)=0.2×0.5+0.8×0.05=0.14。P(迷惑|無料)=0.1/0.14≈0.71。"},{"id":"yoso-153","field":"確率","question":"52枚のトランプから1枚引くとき、ハートまたはキングである確率はいくつか。","choices":["17/52","4/13","1/2","1/13"],"answer":2,"explanation":"ハート13枚+キング4枚−重複(ハートのキング)1枚=16枚。16/52=4/13。"},{"id":"yoso-154","field":"確率変数と確率分布","question":"確率変数Xが値−1, 0, 1をそれぞれ確率0.25, 0.5, 0.25でとるとき、分散V[X]はいくつか。","choices":["0","0.5","1","0.25"],"answer":2,"explanation":"E[X]=0。E[X²]=0.25+0.25=0.5。V[X]=0.5。"},{"id":"yoso-155","field":"確率変数と確率分布","question":"XとYが独立で、V[X]=1、V[Y]=4のとき、V[2X+Y]はいくつか。","choices":["6","8","12","9"],"answer":2,"explanation":"独立なのでV[2X+Y]=4V[X]+V[Y]=4+4=8。"},{"id":"yoso-156","field":"確率変数と確率分布","question":"二項分布B(200, 0.01)をポアソン分布で近似するとき、ポアソン分布の平均はいくつか。","choices":["0.01","2","200","4"],"answer":2,"explanation":"λ=np=200×0.01=2。"},{"id":"yoso-157","field":"正規分布と標本分布","question":"標本サイズを9倍にすると、標本平均の標準誤差はもとの何倍になるか。","choices":["1/9倍","1/3倍","3倍","9倍"],"answer":2,"explanation":"標準誤差はσ/√nなので、√9=3で1/3倍。"},{"id":"yoso-158","field":"正規分布と標本分布","question":"テストの得点がN(60, 100)(分散100)に従うとき、上位10%に入る得点の下限に最も近い値はどれか(上側10%点z=1.28)。","choices":["70.0","72.8","76.4","80.0"],"answer":2,"explanation":"60+1.28×10=72.8。"},{"id":"yoso-159","field":"正規分布と標本分布","question":"t分布について正しいものはどれか。","choices":["自由度が大きくなると標準正規分布に近づく","自由度が大きくなるとχ²分布に近づく","平均は常に1である","左右非対称である"],"answer":1,"explanation":"t分布は0を中心に左右対称で、自由度が大きいと標準正規分布に近づく。"},{"id":"yoso-160","field":"統計的推定","question":"母平均の95%信頼区間が[46, 54](z=1.96を使用)であった。標準誤差に最も近い値はどれか。","choices":["1.0","2.0","4.0","8.0"],"answer":2,"explanation":"半幅は4=1.96×標準誤差。標準誤差≈2.04。"},{"id":"yoso-161","field":"統計的推定","question":"n=5の標本で、nで割った標本分散が8であった。不偏分散はいくつか。","choices":["6.4","8","10","40"],"answer":3,"explanation":"偏差平方和=8×5=40。n−1=4で割って10。"},{"id":"yoso-162","field":"統計的推定","question":"調査で回答拒否が多く、回答者に偏りが生じたことによる誤差は何と呼ばれるか。","choices":["標本誤差","非標本誤差","第1種の過誤","偶然誤差"],"answer":2,"explanation":"標本抽出に伴う偶然のばらつきは標本誤差。回答拒否や測定の誤りによる偏りは非標本誤差。"},{"id":"yoso-163","field":"仮説検定","question":"「新薬は従来薬より効果が高い」ことを示したいとき、帰無仮説として適切なものはどれか。","choices":["新薬と従来薬の効果に差はない","新薬の効果が従来薬より高い","新薬の効果が従来薬より低い","新薬の効果は必ず変わる"],"answer":1,"explanation":"示したい主張を対立仮説に置き、帰無仮説は「差がない」とする。"},{"id":"yoso-164","field":"仮説検定","question":"H0:σ²=25の検定で、n=11、不偏分散s²=40のとき、検定統計量(n−1)s²/σ²はいくつか。","choices":["8","16","1.6","27.5"],"answer":2,"explanation":"10×40/25=16。自由度10のχ²分布と比較する。"},{"id":"yoso-165","field":"仮説検定","question":"両側検定で、t=−2.3、自由度20であった。有意水準5%の臨界値は±2.086である。結論として正しいものはどれか。","choices":["帰無仮説は棄却される","帰無仮説は棄却されない","判断できない","片側検定でのみ棄却される"],"answer":1,"explanation":"|t|=2.3>2.086なので棄却される。"},{"id":"yoso-166","field":"回帰分析と分散分析","question":"回帰直線 y=5+3x において、xが1増えたときのyの予測値の変化はどれか。","choices":["3増える","5増える","8増える","変化しない"],"answer":1,"explanation":"傾き3が、xが1増えたときのyの予測値の変化量。"},{"id":"yoso-167","field":"回帰分析と分散分析","question":"切片を含む最小二乗法による回帰分析で、残差の合計はいくつか。","choices":["0","1","n","分散に等しい"],"answer":1,"explanation":"切片を含む最小二乗法では、残差の総和は0になる。"},{"id":"yoso-168","field":"回帰分析と分散分析","question":"一元配置分散分析で、群間平方和が120(自由度3)、群内平方和が150(自由度15)のとき、F値はいくつか。","choices":["0.8","4.0","1.25","8.0"],"answer":2,"explanation":"F=(120/3)/(150/15)=40/10=4.0。"},{"id":"yoso-169","field":"データの基礎","question":"データ 2, 4, 6 の分散(nで割る)はいくつか。","choices":["2.00","2.67","4.00","18.67"],"answer":2,"explanation":"平均4。偏差平方和=4+0+4=8。8/3≈2.67。E[x²]−平均²=56/3−16=8/3でも同じ。"},{"id":"yoso-170","field":"データの基礎","question":"度数分布表で、階級0〜10の度数が5、10〜20が12、20〜30が8、30〜40が5(計30)のとき、中央値が含まれる階級はどれか。","choices":["0〜10","10〜20","20〜30","30〜40"],"answer":2,"explanation":"中央値は15・16番目。累積度数は5、17なので10〜20の階級。"},{"id":"yoso-171","field":"データの基礎","question":"売上が1年目に前年の0.5倍、2年目に前年の2倍になった。2年間の前年比の幾何平均(年平均倍率)はいくつか。","choices":["0.5","1.0","1.25","2.0"],"answer":2,"explanation":"幾何平均=√(0.5×2)=1.0。算術平均1.25は誤り。"},{"id":"yoso-172","field":"2変数・時系列","question":"偏差平方和がSxx=40、Syy=90、偏差積和がSxy=30のとき、相関係数はいくつか。","choices":["0.33","0.5","0.75","0.25"],"answer":2,"explanation":"r=Sxy/√(Sxx·Syy)=30/√3600=30/60=0.5。"},{"id":"yoso-173","field":"2変数・時系列","question":"名目の経済成長率が5%、物価上昇率が2%のとき、実質の経済成長率に最も近い値はどれか。","choices":["3%","7%","5%","2.5%"],"answer":1,"explanation":"実質成長率≈名目成長率−物価上昇率=3%。(厳密には1.05/1.02−1≈2.94%)"},{"id":"yoso-174","field":"2変数・時系列","question":"時系列 3, 5, 8, 12 の階差(各期から前期を引いた差)の系列はどれか。","choices":["2, 3, 4","3, 5, 8","2, 5, 12","1, 2, 3"],"answer":1,"explanation":"5−3=2、8−5=3、12−8=4。"},{"id":"yoso-175","field":"確率","question":"事象A, Bが独立で、P(A)=0.3、P(B)=0.5のとき、P(A∪B)はいくつか。","choices":["0.8","0.65","0.15","0.35"],"answer":2,"explanation":"独立なのでP(A∩B)=0.15。P(A∪B)=0.3+0.5−0.15=0.65。"},{"id":"yoso-176","field":"確率","question":"当たる確率が0.2のくじを、独立に2回引く。少なくとも1回当たる確率はいくつか。","choices":["0.04","0.36","0.4","0.2"],"answer":2,"explanation":"1−0.8²=1−0.64=0.36。"},{"id":"yoso-177","field":"確率","question":"白玉3個・赤玉2個の袋から、戻さずに2個取り出す。2個目が赤玉である確率はいくつか。","choices":["1/4","2/5","1/2","3/5"],"answer":2,"explanation":"(3/5)(2/4)+(2/5)(1/4)=8/20=2/5。1個目と同じ確率になる(対称性)。"},{"id":"yoso-178","field":"確率変数と確率分布","question":"B(3, 0.3)に従う確率変数Xについて、P(X≥1)はいくつか。","choices":["0.343","0.657","0.9","0.3"],"answer":2,"explanation":"P(X=0)=0.7³=0.343。P(X≥1)=1−0.343=0.657。"},{"id":"yoso-179","field":"確率変数と確率分布","question":"賞金が1000円(確率0.1)、100円(確率0.4)、0円(確率0.5)のくじの賞金の期待値はいくつか。","choices":["100","140","1100","500"],"answer":2,"explanation":"1000×0.1+100×0.4=100+40=140。"},{"id":"yoso-180","field":"確率変数と確率分布","question":"V[X]=9のとき、Y=−2Xの標準偏差はいくつか。","choices":["−6","6","18","36"],"answer":2,"explanation":"V[Y]=4×9=36。標準偏差は√36=6(標準偏差は負にならない)。"},{"id":"yoso-181","field":"正規分布と標本分布","question":"X〜N(20, 4)(平均20、分散4)のとき、P(X≤18)に最も近い値はどれか。","choices":["0.16","0.34","0.68","0.84"],"answer":1,"explanation":"標準偏差2。18は−1σなので、P(Z≤−1)≈0.16。"},{"id":"yoso-182","field":"正規分布と標本分布","question":"母比率0.5の母集団から大きさ400の標本を取るとき、標本比率が0.55以上となる確率に最も近い値はどれか。","choices":["0.023","0.16","0.05","0.5"],"answer":1,"explanation":"標準誤差=√(0.25/400)=0.025。z=(0.55−0.5)/0.025=2。P(Z≥2)≈0.023。"},{"id":"yoso-183","field":"正規分布と標本分布","question":"自由度5のカイ二乗分布の分散はいくつか。","choices":["5","10","25","2.5"],"answer":2,"explanation":"自由度kのχ²分布は平均k、分散2k。分散=10。"},{"id":"yoso-184","field":"統計的推定","question":"母標準偏差10が既知とする。母平均を95%信頼で誤差±2以内に推定するために必要な最小の標本サイズはいくつか(z=1.96)。","choices":["49","97","196","385"],"answer":2,"explanation":"n≥(1.96×10/2)²=96.04。切り上げて97。"},{"id":"yoso-185","field":"統計的推定","question":"n=100で標本比率が0.4のとき、母比率の90%信頼区間(z=1.645)に最も近いものはどれか。","choices":["[0.32, 0.48]","[0.30, 0.50]","[0.34, 0.46]","[0.24, 0.56]"],"answer":1,"explanation":"標準誤差=√(0.24/100)≈0.049。0.4±1.645×0.049≈0.4±0.08。"},{"id":"yoso-186","field":"統計的推定","question":"推定量のバイアスが0.5、分散が1.5のとき、平均二乗誤差(MSE)はいくつか。","choices":["1.5","1.75","2.0","2.25"],"answer":2,"explanation":"MSE=分散+バイアス²=1.5+0.25=1.75。"},{"id":"yoso-187","field":"仮説検定","question":"独立な2標本で、標本1の母分散は18でn=9、標本2の母分散は32でn=16である。標本平均の差が5のとき、z統計量はいくつか。","choices":["1.25","2.5","5","10"],"answer":2,"explanation":"SE=√(2+2)=2。z=5/2=2.5。"},{"id":"yoso-188","field":"仮説検定","question":"検定の結果、帰無仮説が棄却されなかった。この結果の説明として最も適切なものはどれか。","choices":["帰無仮説が正しいことが証明された","帰無仮説を棄却するだけの十分な証拠が得られなかった","対立仮説が正しいと証明された","第1種の過誤が起きた"],"answer":2,"explanation":"棄却されないことは、帰無仮説が正しいことの証明ではない。証拠が不十分というだけ。"},{"id":"yoso-189","field":"仮説検定","question":"6つの区分について、母数を推定せずに適合度のカイ二乗検定を行うとき、自由度はいくつか。","choices":["4","5","6","7"],"answer":2,"explanation":"自由度=区分数−1=5。"},{"id":"yoso-190","field":"回帰分析と分散分析","question":"Sxy=30、Sxx=40のとき、単回帰の回帰係数(傾き)はいくつか。","choices":["0.75","1.33","0.5","1.5"],"answer":1,"explanation":"b=Sxy/Sxx=30/40=0.75。"},{"id":"yoso-191","field":"回帰分析と分散分析","question":"3群・合計18個のデータによる一元配置分散分析で、群内(残差)の自由度はいくつか。","choices":["2","15","17","18"],"answer":2,"explanation":"群内の自由度=N−群数=18−3=15。群間は2、全体は17。"},{"id":"yoso-192","field":"回帰分析と分散分析","question":"重回帰式 y=1+2x1−3x2 で、x1=2、x2=1のときの予測値はいくつか。","choices":["2","4","5","8"],"answer":1,"explanation":"1+2×2−3×1=2。"},{"id":"yoso-193","field":"データの基礎","question":"5個のデータの平均が10である。このうち値が20のデータを1つ除いた残り4個の平均はいくつか。","choices":["7.5","8.0","10","12.5"],"answer":1,"explanation":"合計は50。20を除くと合計30。30/4=7.5。"},{"id":"yoso-194","field":"データの基礎","question":"平均と標準偏差がわかっているデータで、分布の形を問わずに「平均±2標準偏差」の範囲に少なくとも何%のデータが入ると言えるか(チェビシェフの不等式)。","choices":["68%","75%","95%","99.7%"],"answer":2,"explanation":"チェビシェフの不等式は1−1/k²。k=2で少なくとも75%。95%は正規分布の場合。"},{"id":"yoso-195","field":"データの基礎","question":"データの単位がcmのとき、分散の単位はどれか。","choices":["cm","cm²","単位なし","cm³"],"answer":2,"explanation":"分散は偏差の2乗の平均なので単位もcm²。標準偏差はcm。"},{"id":"yoso-196","field":"2変数・時系列","question":"2変数の相関係数が−0.6のとき、相関係数の2乗r²はいくつか。","choices":["0.36","0.6","−0.36","0.77"],"answer":1,"explanation":"(−0.6)²=0.36。二乗すると符号は正になる。"},{"id":"yoso-197","field":"2変数・時系列","question":"2020年=100の指数で、2023年が120であった。2023年=100に基準を変更すると、2020年の指数はいくつになるか。","choices":["80","83.3","120","20"],"answer":2,"explanation":"100/120×100≈83.3。"},{"id":"yoso-198","field":"2変数・時系列","question":"加法モデル(原系列=傾向変動+季節変動+不規則変動)で、ある月の実測値が150、傾向変動が130、不規則変動が5のとき、季節変動はいくつか。","choices":["5","15","20","25"],"answer":2,"explanation":"150−130−5=15。"},{"id":"yoso-199","field":"確率","question":"P(A∩B)=0.1、P(A∩Bᶜ)=0.3のとき、P(A)はいくつか。","choices":["0.4","0.3","0.1","0.13"],"answer":1,"explanation":"AはBとBᶜに分けられるのでP(A)=0.1+0.3=0.4。"},{"id":"yoso-200","field":"確率","question":"公平なサイコロを2回振る。目の積が奇数になる確率はいくつか。","choices":["1/4","1/3","1/2","3/4"],"answer":1,"explanation":"積が奇数になるのは両方奇数のとき。(1/2)×(1/2)=1/4。"},{"id":"yoso-201","field":"確率","question":"有病率が1%、感度が95%、偏陽性率(病気でない人の陽性率)が5%の検査で陽性となった人が実際に病気である確率に最も近い値はどれか。","choices":["0.95","0.16","0.05","0.01"],"answer":2,"explanation":"P(陽性)=0.01×0.95+0.99×0.05=0.059。P(病気|陽性)=0.0095/0.059≈0.16。"},{"id":"yoso-202","field":"確率変数と確率分布","question":"X〜B(10, 0.2)の標準偏差に最も近い値はどれか。","choices":["1.26","1.6","2","0.8"],"answer":1,"explanation":"分散=10×0.2×0.8=1.6。標準偏差=√1.6≈1.26。"},{"id":"yoso-203","field":"確率変数と確率分布","question":"独立な確率変数X〜ポアソン分布(平均2)、Y〜ポアソン分布(平均3)のとき、X+Yの分布はどれか。","choices":["ポアソン分布(平均5)","ポアソン分布(平均6)","二項分布","正規分布N(5, 25)"],"answer":1,"explanation":"独立なポアソン分布の和はポアソン分布で、平均は2+3=5。"},{"id":"yoso-204","field":"確率変数と確率分布","question":"Cov(X, Y)=1.5のとき、Cov(2X, 3Y)はいくつか。","choices":["4.5","5","9","1.5"],"answer":3,"explanation":"Cov(aX, bY)=ab·Cov(X, Y)=6×1.5=9。"},{"id":"yoso-205","field":"正規分布と標本分布","question":"平均50の正規分布で、X≥70となる確率が約2.3%である。標準偏差はいくつか。","choices":["5","10","20","40"],"answer":2,"explanation":"上側2.3%はz=2に相当。(70−50)/σ=2よりσ=10。"},{"id":"yoso-206","field":"正規分布と標本分布","question":"母平均100、母標準偏差20の母集団からn=100の標本を取る。標本平均が103以上となる確率に最も近い値はどれか。","choices":["0.0668","0.1587","0.0228","0.3085"],"answer":1,"explanation":"標準誤差=20/10=2。z=(103−100)/2=1.5。P(Z≥1.5)≈0.0668。"},{"id":"yoso-207","field":"正規分布と標本分布","question":"母分散25の母集団から大きさnの標本を取る。不偏分散s²の期待値はいくつか。","choices":["25","25(n−1)/n","5","n×25"],"answer":1,"explanation":"不偏分散の期待値は母分散に等しい。nで割る標本分散は25(n−1)/n。"},{"id":"yoso-208","field":"統計的推定","question":"独立な2標本の平均の差が5、その標準誤差が2(母分散既知)のとき、母平均の差の95%信頼区間(z=1.96)はどれか。","choices":["[1.08, 8.92]","[3.0, 7.0]","[−3.92, 3.92]","[0.0, 10.0]"],"answer":1,"explanation":"5±1.96×2=5±3.92。"},{"id":"yoso-209","field":"統計的推定","question":"層A(600人)と層B(400人)からなる母集団から、比例配分の層化抽出で100人を抽出するとき、層Aから何人抽出するか。","choices":["40","50","60","600"],"answer":3,"explanation":"層の大きさに比例して100×600/1000=60人。"},{"id":"yoso-210","field":"統計的推定","question":"同じ母数を推定する2つの不偏推定量のうち、より有効な推定量とされるのはどれか。","choices":["分散が小さい方","分散が大きい方","標本サイズが小さい方","バイアスが大きい方"],"answer":1,"explanation":"不偏推定量どうしでは分散が小さい方が有効(効率的)。"},{"id":"yoso-211","field":"仮説検定","question":"帰無仮説がすべて正しい状況で、有意水準5%の独立な検定を10回行う。少なくとも1回帰無仮説を棄却してしまう確率に最も近い値はどれか。","choices":["0.05","0.40","0.50","0.95"],"answer":2,"explanation":"1−0.95¹⁰≈1−0.599=0.40。検定を繰り返すと第1種の過誤が起きやすくなる(多重検定の問題)。"},{"id":"yoso-212","field":"仮説検定","question":"検定統計量z=1.8であった。結論として正しいものはどれか(上側5%点=1.645、上側2.5%点=1.96)。","choices":["片側(上側)5%でも両側5%でも棄却","片側(上側)5%では棄却、両側5%では棄却されない","片側(上側)5%では棄却されず、両側5%では棄却","どちらも棄却されない"],"answer":2,"explanation":"1.8>1.645なので片側では棄却。1.8<1.96なので両側では棄却されない。"},{"id":"yoso-213","field":"仮説検定","question":"2×2分割表の独立性のカイ二乗検定の自由度はいくつか。","choices":["1","2","3","4"],"answer":1,"explanation":"(2−1)(2−1)=1。"},{"id":"yoso-214","field":"回帰分析と分散分析","question":"xとyをどちらも標準化(平均0・標準偏差1)して単回帰したとき、相関係数が0.7なら傾きはいくつか。","choices":["0.49","0.7","1.0","0.84"],"answer":2,"explanation":"傾き=r×(sy/sx)=0.7×1=0.7。"},{"id":"yoso-215","field":"回帰分析と分散分析","question":"単回帰分析で、n=20、残差平方和が36のとき、誤差分散の不偏推定値はいくつか。","choices":["1.8","2.0","2.25","36"],"answer":2,"explanation":"残差平方和/(n−2)=36/18=2.0。"},{"id":"yoso-216","field":"回帰分析と分散分析","question":"一元配置分散分析の前提として、必要ではないものはどれか。","choices":["各群が正規分布に従う","各群の母分散が等しい","観測値が独立である","各群の標本サイズが必ず等しい"],"answer":4,"explanation":"正規性・等分散・独立性が前提。サイズが等しいことは必須ではない。"},{"id":"yoso-217","field":"データの基礎","question":"データ 1, 2, 3, 4, 5 の標本標準偏差(不偏分散の平方根)に最も近い値はどれか。","choices":["1.41","1.58","2.5","2.0"],"answer":2,"explanation":"偏差平方和=10、不偏分散=10/4=2.5、標準偏差=√2.5≈1.58。nで割ると√2≈1.41。"},{"id":"yoso-218","field":"データの基礎","question":"データ 1, 2, 3, 4, 5, 6, 7, 8, 9 の四分位範囲はいくつか(中央値を除いて下位半分と上位半分の中央値を第1・第3四分位数とする)。","choices":["4","5","6","8"],"answer":2,"explanation":"下位半分(1〜4)の中央値は2.5、上位半分(6〜9)の中央値は7.5。差は5。"},{"id":"yoso-219","field":"データの基礎","question":"すべてのデータに10を加えたとき、平均と分散はどう変わるか。","choices":["平均は10増え、分散は変わらない","平均は10増え、分散は100増える","平均は変わらず、分散は10増える","平均も分散もともに10増える"],"answer":1,"explanation":"定数を加えると平均はその分ずれるが、ばらつき(分散・標準偏差)は変わらない。"},{"id":"yoso-220","field":"2変数・時系列","question":"yをxに回帰した傾きが1.2、xの標準偏差が5、yの標準偏差が10のとき、相関係数はいくつか。","choices":["0.6","2.4","1.2","0.3"],"answer":1,"explanation":"b=r×sy/sx より r=b×sx/sy=1.2×5/10=0.6。"},{"id":"yoso-221","field":"2変数・時系列","question":"指数平滑法 S_t=αx_t+(1−α)S_(t−1) で、α=0.5、S_(t−1)=10、x_t=14のとき、S_tはいくつか。","choices":["12","14","10","24"],"answer":1,"explanation":"0.5×14+0.5×10=12。"},{"id":"yoso-222","field":"2変数・時系列","question":"売上が2年間で10→121になった。毎年同じ割合で増加したとすると、年平均成長率はいくつか。","choices":["10%","10.5%","21%","5%"],"answer":1,"explanation":"121/100=1.21=1.1²なので、年平均成長率は10%。"},{"id":"yoso-223","field":"確率","question":"P(A)=0.5、P(B)=0.4、P(A|B)=0.5のとき、AとBの関係として正しいものはどれか。","choices":["排反","独立","互いの余事象","独立ではない"],"answer":2,"explanation":"P(A|B)=P(A)なので独立。P(A∩B)=0.2=0.5×0.4。"},{"id":"yoso-224","field":"確率","question":"2人がじゃんけんをしたとき、あいこになる確率はいくつか(各自グー・チョキ・パーを等確率で出す)。","choices":["1/3","1/2","1/9","2/3"],"answer":1,"explanation":"全体9通りのうちあいこは3通り。3/9=1/3。"},{"id":"yoso-225","field":"確率","question":"雨の日が30%、雨の日の遅刻確率が40%、晴れの日の遅刻確率が10%である。遅刻した日が雨だった確率に最も近い値はどれか。","choices":["0.3","0.63","0.4","0.12"],"answer":2,"explanation":"P(遅刻)=0.3×0.4+0.7×0.1=0.19。P(雨|遅刻)=0.12/0.19≈0.63。"},{"id":"yoso-226","field":"確率変数と確率分布","question":"区間[2, 8]上の連続一様分布に従う確率変数の期待値はいくつか。","choices":["4","5","6","10"],"answer":2,"explanation":"一様分布の期待値は(a+b)/2=5。"},{"id":"yoso-227","field":"確率変数と確率分布","question":"X〜B(5, 0.4)、Y〜B(7, 0.4)が独立のとき、X+Yの期待値はいくつか。","choices":["4.8","2.4","12","0.4"],"answer":1,"explanation":"X+Y〜B(12, 0.4)。期待値=12×0.4=4.8。"},{"id":"yoso-228","field":"確率変数と確率分布","question":"E[X²]=10、E[X]=2のとき、V[X]はいくつか。","choices":["4","6","8","12"],"answer":2,"explanation":"V[X]=E[X²]−(E[X])²=10−4=6。"},{"id":"yoso-229","field":"正規分布と標本分布","question":"X〜B(100, 0.5)を正規分布で近似(連続修正なし)するとき、P(X≤45)に最も近い値はどれか。","choices":["0.16","0.023","0.31","0.84"],"answer":1,"explanation":"平均50、標準偏差5。z=(45−50)/5=−1。P(Z≤−1)≈0.16。"},{"id":"yoso-230","field":"正規分布と標本分布","question":"母集団が正規分布でないとき、標本サイズが5の標本平均について最も適切なものはどれか。","choices":["常に正規分布に従う","標本サイズが小さいと正規分布への近似が悪い場合がある","必ずt分布に従う","必ず母集団と同じ分布に従う"],"answer":2,"explanation":"中心極限定理は標本サイズが大きいときの近似で、小さいと母集団の形の影響が残る。"},{"id":"yoso-231","field":"正規分布と標本分布","question":"独立な2つの正規母集団からn1=8、n2=11の標本を取り、不偏分散の比(第1標本/第2標本)をとる。等分散のもとでこの比が従う分布はどれか。","choices":["F(8, 11)","F(7, 10)","F(10, 7)","F(19)"],"answer":2,"explanation":"自由度は(n1−1, n2−1)=(7, 10)。"},{"id":"yoso-232","field":"統計的推定","question":"母分散が未知で、同じ標本・同じ信頼係数のとき、t分布を用いた母平均の信頼区間は、標準正規分布を用いた区間と比べてどうなるか。","choices":["広くなる","狭くなる","同じになる","定まらない"],"answer":1,"explanation":"t分布の裾は正規分布より重いため、臨界値が大きく区間は広くなる。"},{"id":"yoso-233","field":"統計的推定","question":"母比率を95%信頼で誤差±0.03以内に推定したい。母比率が不明(p=0.5とみなす)のとき、必要な最小の標本サイズはいくつか(z=1.96)。","choices":["385","1068","1537","4268"],"answer":2,"explanation":"n≥(1.96/0.03)²×0.25≈1067.1。切り上げて1068。"},{"id":"yoso-234","field":"統計的推定","question":"母平均や母分散など、母集団の分布を特徴づける未知の定数を何というか。","choices":["統計量","母数","推定量","標本"],"answer":2,"explanation":"母数(パラメータ)。統計量は標本から計算して得る量。"},{"id":"yoso-235","field":"仮説検定","question":"3つ以上の群の母平均がすべて等しいかを検定するとき、最も適切な方法はどれか。","choices":["2群ずつt検定を繰り返す","分散分析(F検定)","適合度のχ²検定","対応のあるt検定"],"answer":2,"explanation":"多群の平均差は分散分析。t検定の繰り返しは第1種の過誤が膨らむ。"},{"id":"yoso-236","field":"仮説検定","question":"2×2分割表の観測度数が [[20, 30], [30, 20]] のとき、独立性のχ²統計量はいくつか。","choices":["1","2","4","25"],"answer":3,"explanation":"期待度数はすべてのセル、25。各セル(5²/25=1)の和で4。"},{"id":"yoso-237","field":"仮説検定","question":"標準正規分布を用いた上側片側検定で、z=2.326のとき、P値に最も近い値はどれか。","choices":["0.005","0.01","0.02","0.05"],"answer":2,"explanation":"z=2.326は上側1%点なので、片側P値は約0.01。"},{"id":"yoso-238","field":"回帰分析と分散分析","question":"単回帰分析で、n=12、決定係数R²=0.5のとき、回帰の有意性を検定するF値はいくつか。","choices":["5","10","12","1"],"answer":2,"explanation":"F=R²/(1−R²)×(n−2)=1×10=10。"},{"id":"yoso-239","field":"回帰分析と分散分析","question":"回帰平方和90(自由度1)、残差平方和40(自由度8)のとき、F値はいくつか。","choices":["9","18","2.25","11.25"],"answer":2,"explanation":"F=(90/1)/(40/8)=90/5=18。"},{"id":"yoso-240","field":"回帰分析と分散分析","question":"説明変数x_jを他の説明変数で回帰したときの決定係数が0.9のとき、VIF(=1/(1−R²))はいくつか。","choices":["0.9","9","10","11.1"],"answer":3,"explanation":"VIF=1/(1−0.9)=10。大きいほど多重共線性が強い。"},{"id":"yoso-241","field":"データの基礎","question":"5個のデータ 9, 1, 15, 6, 22 の不偏分散(n−1で割る分散)はいくつか。","choices":["8.14","265.20","53.04","66.30"],"answer":4,"explanation":"平均は10.6、偏差平方和は265.2。n−1=4で割って66.30。nで割ると53.04。"},{"id":"yoso-242","field":"データの基礎","question":"5個のデータ 19, 6, 16, 17, 13 の不偏分散(n−1で割る分散)はいくつか。","choices":["20.56","102.80","5.07","25.70"],"answer":4,"explanation":"平均は14.2、偏差平方和は102.8。n−1=4で割って25.70。nで割ると20.56。"},{"id":"yoso-243","field":"データの基礎","question":"5個のデータ 6, 9, 11, 15, 19 の不偏分散(n−1で割る分散)はいくつか。","choices":["5.10","26.00","104.00","20.80"],"answer":2,"explanation":"平均は12、偏差平方和は104。n−1=4で割って26.00。nで割ると20.80。"},{"id":"yoso-244","field":"データの基礎","question":"5個のデータ 11, 6, 1, 18, 3 の不偏分散(n−1で割る分散)はいくつか。","choices":["46.70","6.83","37.36","186.80"],"answer":1,"explanation":"平均は7.8、偏差平方和は186.8。n−1=4で割って46.70。nで割ると37.36。"},{"id":"yoso-245","field":"データの基礎","question":"A組30人の平均点が65点、B組50人の平均点が90点のとき、80人全体の平均点はいくつか。","choices":["74.4","81.6","80.6","77.5"],"answer":3,"explanation":"加重平均=(30×65+50×90)/80=80.6。単純平均77.5は人数を考慮していないので誤り。"},{"id":"yoso-246","field":"データの基礎","question":"A組30人の平均点が65点、B組40人の平均点が90点のとき、70人全体の平均点はいくつか。","choices":["79.3","80.3","77.5","75.7"],"answer":1,"explanation":"加重平均=(30×65+40×90)/70=79.3。単純平均77.5は人数を考慮していないので誤り。"},{"id":"yoso-247","field":"データの基礎","question":"A組30人の平均点が55点、B組20人の平均点が90点のとき、50人全体の平均点はいくつか。","choices":["69.0","70.0","76.0","72.5"],"answer":1,"explanation":"加重平均=(30×55+20×90)/50=69.0。単純平均72.5は人数を考慮していないので誤り。"},{"id":"yoso-248","field":"データの基礎","question":"データ 3, 36, 27, 25, 20, 19 の中央値はいくつか。","choices":["20","21.6667","25","22.5"],"answer":4,"explanation":"小さい順に3, 19, 20, 25, 27, 36。n=6は偶数なので中央の2つ(20と25)の平均22.5。"},{"id":"yoso-249","field":"データの基礎","question":"データ 19, 9, 32, 23, 37, 1 の中央値はいくつか。","choices":["23","20.1667","19","21"],"answer":4,"explanation":"小さい順に1, 9, 19, 23, 32, 37。n=6は偶数なので中央の2つ(19と23)の平均21。"},{"id":"yoso-250","field":"データの基礎","question":"データ 13, 10, 39, 38, 4, 32 の中央値はいくつか。","choices":["22.6667","22.5","13","32"],"answer":2,"explanation":"小さい順に4, 10, 13, 32, 38, 39。n=6は偶数なので中央の2つ(13と32)の平均22.5。"},{"id":"yoso-251","field":"データの基礎","question":"平均50点、標準偏差12点の試験で68点を取った人の偏差値はいくつか。","choices":["51.5","65","35","15"],"answer":2,"explanation":"z=(68−50)/12=1.5。偏差値=50+10z=65。"},{"id":"yoso-252","field":"データの基礎","question":"平均50点、標準偏差10点の試験で45点を取った人の偏差値はいくつか。","choices":["49.5","-5","55","45"],"answer":4,"explanation":"z=(45−50)/10=-0.5。偏差値=50+10z=45。"},{"id":"yoso-253","field":"データの基礎","question":"平均70点、標準偏差20点の試験で90点を取った人の偏差値はいくつか。","choices":["40","51","60","10"],"answer":3,"explanation":"z=(90−70)/20=1。偏差値=50+10z=60。"},{"id":"yoso-254","field":"データの基礎","question":"平均65点、標準偏差16点の試験で81点を取った人の偏差値はいくつか。","choices":["40","10","51","60"],"answer":4,"explanation":"z=(81−65)/16=1。偏差値=50+10z=60。"},{"id":"yoso-255","field":"データの基礎","question":"平均80、標準偏差20のデータの変動係数はいくつか。","choices":["4.00","0.25","25.0","5.00"],"answer":2,"explanation":"変動係数=標準偏差/平均=20/80=0.25。"},{"id":"yoso-256","field":"データの基礎","question":"平均40、標準偏差12のデータの変動係数はいくつか。","choices":["3.33","0.30","3.60","30.0"],"answer":2,"explanation":"変動係数=標準偏差/平均=12/40=0.30。"},{"id":"yoso-257","field":"データの基礎","question":"平均60、標準偏差9のデータの変動係数はいくつか。","choices":["0.15","1.35","15.0","6.67"],"answer":1,"explanation":"変動係数=標準偏差/平均=9/60=0.15。"},{"id":"yoso-258","field":"データの基礎","question":"データ 3, 45, 49, 39, 38, 4, 2, 55 の四分位範囲はいくつか(データを下位半分と上位半分に分け、それぞれの中央値を第1・第3四分位数とする)。","choices":["3.5","47","53","43.5"],"answer":4,"explanation":"小さい順に2, 3, 4, 38, 39, 45, 49, 55。Q1=3.5、Q3=47。四分位範囲=43.5(範囲53とは異なる)。"},{"id":"yoso-259","field":"データの基礎","question":"データ 7, 59, 13, 31, 15, 34, 56, 37 の四分位範囲はいくつか(データを下位半分と上位半分に分け、それぞれの中央値を第1・第3四分位数とする)。","choices":["32.5","14","52","46.5"],"answer":1,"explanation":"小さい順に7, 13, 15, 31, 34, 37, 56, 59。Q1=14、Q3=46.5。四分位範囲=32.5(範囲52とは異なる)。"},{"id":"yoso-260","field":"データの基礎","question":"データ 23, 40, 56, 31, 33, 9, 39, 57 の四分位範囲はいくつか(データを下位半分と上位半分に分け、それぞれの中央値を第1・第3四分位数とする)。","choices":["23","48","27","21"],"answer":4,"explanation":"小さい順に9, 23, 31, 33, 39, 40, 56, 57。Q1=27、Q3=48。四分位範囲=21(範囲48とは異なる)。"},{"id":"yoso-261","field":"2変数・時系列","question":"x, yの標本共分散が24、xの標準偏差が5、yの標準偏差が6のとき、相関係数はいくつか。","choices":["0.80","0.027","4.80","4.00"],"answer":1,"explanation":"r=共分散/(sx×sy)=24/30=0.80。"},{"id":"yoso-262","field":"2変数・時系列","question":"x, yの標本共分散が-24、xの標準偏差が10、yの標準偏差が6のとき、相関係数はいくつか。","choices":["-2.40","-4.00","-0.007","-0.40"],"answer":4,"explanation":"r=共分散/(sx×sy)=-24/60=-0.40。"},{"id":"yoso-263","field":"2変数・時系列","question":"x, yの標本共分散が4.2、xの標準偏差が2、yの標準偏差が3のとき、相関係数はいくつか。","choices":["0.70","1.40","2.10","0.117"],"answer":1,"explanation":"r=共分散/(sx×sy)=4.2/6=0.70。"},{"id":"yoso-264","field":"2変数・時系列","question":"時系列(第1〜6期) 16, 24, 18, 12, 24, 28 について、第5期を中心とする3項移動平均はいくつか。","choices":["21.33","24.00","18.00","20.33"],"answer":1,"explanation":"第4〜6期の平均=(12+24+28)/3=21.33。"},{"id":"yoso-265","field":"2変数・時系列","question":"時系列(第1〜6期) 29, 25, 18, 36, 38, 23 について、第3期を中心とする3項移動平均はいくつか。","choices":["24.00","30.67","26.33","18.00"],"answer":3,"explanation":"第2〜4期の平均=(25+18+36)/3=26.33。"},{"id":"yoso-266","field":"2変数・時系列","question":"時系列(第1〜6期) 37, 20, 17, 29, 34, 27 について、第5期を中心とする3項移動平均はいくつか。","choices":["34.00","27.33","30.00","26.67"],"answer":3,"explanation":"第4〜6期の平均=(29+34+27)/3=30.00。"},{"id":"yoso-267","field":"2変数・時系列","question":"2財の価格は基準時点で150円・150円、比較時点で195円・180円。数量は基準時点で11個・3個、比較時点で9個・6個である。ラスパイレス価格指数(基準=100)はいくつか。","choices":["127.9","126.9","126.0","132.9"],"answer":1,"explanation":"基準時点の数量で加重。Σp1q0/Σp0q0×100=127.9。パーシェ指数は126.0。"},{"id":"yoso-268","field":"2変数・時系列","question":"2財の価格は基準時点で50円・100円、比較時点で65円・150円。数量は基準時点で2個・9個、比較時点で2個・8個である。ラスパイレス価格指数(基準=100)はいくつか。","choices":["153.0","147.9","147.8","148.0"],"answer":4,"explanation":"基準時点の数量で加重。Σp1q0/Σp0q0×100=148.0。パーシェ指数は147.8。"},{"id":"yoso-269","field":"2変数・時系列","question":"2財の価格は基準時点で150円・100円、比較時点で135円・110円。数量は基準時点で10個・8個、比較時点で12個・8個である。パーシェ価格指数(基準=100)はいくつか。","choices":["96.6","101.2","97.0","96.2"],"answer":4,"explanation":"比較時点の数量で加重。Σp1q1/Σp0q1×100=96.2。ラスパイレス指数は97.0。"},{"id":"yoso-270","field":"2変数・時系列","question":"2財の価格は基準時点で200円・150円、比較時点で260円・135円。数量は基準時点で6個・9個、比較時点で5個・9個である。パーシェ価格指数(基準=100)はいくつか。","choices":["112.0","107.0","108.8","107.9"],"answer":2,"explanation":"比較時点の数量で加重。Σp1q1/Σp0q1×100=107.0。ラスパイレス指数は108.8。"},{"id":"yoso-271","field":"2変数・時系列","question":"名目の売上が630、デフレーター(基準年=100)が80のとき、実質の売上はいくつか。","choices":["787.5","550.0","504.0","7.9"],"answer":1,"explanation":"実質値=名目値/デフレーター×100=630/80×100=787.5。"},{"id":"yoso-272","field":"2変数・時系列","question":"名目の売上が300、デフレーター(基準年=100)が120のとき、実質の売上はいくつか。","choices":["360.0","2.5","180.0","250.0"],"answer":4,"explanation":"実質値=名目値/デフレーター×100=300/120×100=250.0。"},{"id":"yoso-273","field":"2変数・時系列","question":"名目の売上が240、デフレーター(基準年=100)が125のとき、実質の売上はいくつか。","choices":["1.9","192.0","300.0","115.0"],"answer":2,"explanation":"実質値=名目値/デフレーター×100=240/125×100=192.0。"},{"id":"yoso-274","field":"2変数・時系列","question":"売上が3年間で100から172.8に増えた。毎年同じ割合で成長したとすると、年平均成長率(幾何平均による)は何%か。","choices":["14.6531%","20%","24.2667%","72.8%"],"answer":2,"explanation":"(172.8/100)=(1+g)^3=1.728より g=20%。単純に総増加率72.8%を3で割った24.2667%は誤り。"},{"id":"yoso-275","field":"2変数・時系列","question":"売上が2年間で200から288に増えた。毎年同じ割合で成長したとすると、年平均成長率(幾何平均による)は何%か。","choices":["22%","12.9243%","20%","44%"],"answer":3,"explanation":"(288/200)=(1+g)^2=1.44より g=20%。単純に総増加率44%を2で割った22%は誤り。"},{"id":"yoso-276","field":"2変数・時系列","question":"売上が2年間で100から144に増えた。毎年同じ割合で成長したとすると、年平均成長率(幾何平均による)は何%か。","choices":["12.9243%","44%","20%","22%"],"answer":3,"explanation":"(144/100)=(1+g)^2=1.44より g=20%。単純に総増加率44%を2で割った22%は誤り。"},{"id":"yoso-277","field":"2変数・時系列","question":"売上が3年間で200から345.6に増えた。毎年同じ割合で成長したとすると、年平均成長率(幾何平均による)は何%か。","choices":["24.2667%","20%","14.6531%","72.8%"],"answer":2,"explanation":"(345.6/200)=(1+g)^3=1.728より g=20%。単純に総増加率72.8%を3で割った24.2667%は誤り。"},{"id":"yoso-278","field":"2変数・時系列","question":"4組のデータ (x, y)=(7,1), (2,2), (1,1), (3,8) の共分散(nで割る)はいくつか。","choices":["-0.75","-3.00","-1.00","0.75"],"answer":1,"explanation":"x̄=3.25、ȳ=3。偏差積和=-3。n=4で割って-0.75。"},{"id":"yoso-279","field":"2変数・時系列","question":"4組のデータ (x, y)=(8,4), (3,6), (6,7), (9,6) の共分散(nで割る)はいくつか。","choices":["-1.17","0.88","-0.88","-3.50"],"answer":3,"explanation":"x̄=6.5、ȳ=5.75。偏差積和=-3.5。n=4で割って-0.88。"},{"id":"yoso-280","field":"2変数・時系列","question":"4組のデータ (x, y)=(7,6), (8,5), (2,2), (7,3) の共分散(nで割る)はいくつか。","choices":["3.67","11.00","-2.75","2.75"],"answer":4,"explanation":"x̄=6、ȳ=4。偏差積和=11。n=4で割って2.75。"},{"id":"yoso-281","field":"確率","question":"P(A)=0.6、P(B)=0.5、P(A∩B)=0.05のとき、P(A∪B)はいくつか。","choices":["0.30","1.15","1.05","1.10"],"answer":3,"explanation":"加法定理 P(A∪B)=P(A)+P(B)−P(A∩B)=0.6+0.5−0.05=1.05。"},{"id":"yoso-282","field":"確率","question":"P(A)=0.4、P(B)=0.4、P(A∩B)=0.15のとき、P(A∪B)はいくつか。","choices":["0.80","0.95","0.16","0.65"],"answer":4,"explanation":"加法定理 P(A∪B)=P(A)+P(B)−P(A∩B)=0.4+0.4−0.15=0.65。"},{"id":"yoso-283","field":"確率","question":"P(A)=0.3、P(B)=0.5、P(A∩B)=0.15のとき、P(A∪B)はいくつか。","choices":["0.95","0.15","0.80","0.65"],"answer":4,"explanation":"加法定理 P(A∪B)=P(A)+P(B)−P(A∩B)=0.3+0.5−0.15=0.65。"},{"id":"yoso-284","field":"確率","question":"P(B)=0.5、P(A∩B)=0.12のとき、条件付き確率P(A|B)はいくつか。","choices":["0.240","4.167","0.120","0.060"],"answer":1,"explanation":"P(A|B)=P(A∩B)/P(B)=0.12/0.5=0.240。"},{"id":"yoso-285","field":"確率","question":"P(B)=0.6、P(A∩B)=0.24のとき、条件付き確率P(A|B)はいくつか。","choices":["0.144","2.500","0.400","0.240"],"answer":3,"explanation":"P(A|B)=P(A∩B)/P(B)=0.24/0.6=0.400。"},{"id":"yoso-286","field":"確率","question":"P(B)=0.3、P(A∩B)=0.1のとき、条件付き確率P(A|B)はいくつか。","choices":["0.333","0.100","3.000","0.030"],"answer":1,"explanation":"P(A|B)=P(A∩B)/P(B)=0.1/0.3=0.333。"},{"id":"yoso-287","field":"確率","question":"ある病気の有病率は1%、検査の感度は95%、病気でない人が陽性となる確率は10%である。陽性だった人が実際に病気である確率に最も近い値はどれか。","choices":["0.95","0.90","0.01","0.09"],"answer":4,"explanation":"P(陽性)=0.01×0.95+0.99×0.1=0.1085。P(病気|陽性)=0.0095/0.1085≈0.088。"},{"id":"yoso-288","field":"確率","question":"ある病気の有病率は1%、検査の感度は80%、病気でない人が陽性となる確率は20%である。陽性だった人が実際に病気である確率に最も近い値はどれか。","choices":["0.008","0.01","0.04","0.80"],"answer":3,"explanation":"P(陽性)=0.01×0.8+0.99×0.2=0.2060。P(病気|陽性)=0.0080/0.2060≈0.039。"},{"id":"yoso-289","field":"確率","question":"ある病気の有病率は2%、検査の感度は95%、病気でない人が陽性となる確率は10%である。陽性だった人が実際に病気である確率に最も近い値はどれか。","choices":["0.95","0.02","0.90","0.16"],"answer":4,"explanation":"P(陽性)=0.02×0.95+0.98×0.1=0.1170。P(病気|陽性)=0.0190/0.1170≈0.162。"},{"id":"yoso-290","field":"確率","question":"ある病気の有病率は5%、検査の感度は90%、病気でない人が陽性となる確率は20%である。陽性だった人が実際に病気である確率に最も近い値はどれか。","choices":["0.19","0.80","0.05","0.90"],"answer":1,"explanation":"P(陽性)=0.05×0.9+0.95×0.2=0.2350。P(病気|陽性)=0.0450/0.2350≈0.191。"},{"id":"yoso-291","field":"確率","question":"7人の中から3人を選ぶ方法(順序は考えない)は何通りか。","choices":["343","35","210","42"],"answer":2,"explanation":"7C3=35。順列7P3=210は順序を区別する場合。"},{"id":"yoso-292","field":"確率","question":"8人の中から4人を選ぶ方法(順序は考えない)は何通りか。","choices":["70","1680","4096","78"],"answer":1,"explanation":"8C4=70。順列8P4=1680は順序を区別する場合。"},{"id":"yoso-293","field":"確率","question":"10人の中から3人を選ぶ方法(順序は考えない)は何通りか。","choices":["1000","120","720","130"],"answer":2,"explanation":"10C3=120。順列10P3=720は順序を区別する場合。"},{"id":"yoso-294","field":"確率","question":"8人の中から2人を選ぶ方法(順序は考えない)は何通りか。","choices":["56","36","28","64"],"answer":3,"explanation":"8C2=28。順列8P2=56は順序を区別する場合。"},{"id":"yoso-295","field":"確率","question":"成功確率0.2の試行を独立に5回行う。少なくとも1回成功する確率に最も近い値はどれか。","choices":["1.000","0.328","0.672","0.000"],"answer":3,"explanation":"余事象を使う。1−(1−0.2)^5=0.672。"},{"id":"yoso-296","field":"確率","question":"成功確率0.2の試行を独立に2回行う。少なくとも1回成功する確率に最も近い値はどれか。","choices":["0.960","0.400","0.360","0.640"],"answer":3,"explanation":"余事象を使う。1−(1−0.2)^2=0.360。"},{"id":"yoso-297","field":"確率","question":"成功確率0.2の試行を独立に4回行う。少なくとも1回成功する確率に最も近い値はどれか。","choices":["0.590","0.410","0.998","0.800"],"answer":1,"explanation":"余事象を使う。1−(1−0.2)^4=0.590。"},{"id":"yoso-298","field":"確率","question":"赤玉4個・白玉2個の袋から、戻さずに2個取り出す。2個とも赤玉である確率はどれか。","choices":["1/3","4/15","2/5","4/9"],"answer":3,"explanation":"4/6×3/5=2/5。戻す場合の4/9とは異なる。"},{"id":"yoso-299","field":"確率","question":"赤玉3個・白玉4個の袋から、戻さずに2個取り出す。2個とも赤玉である確率はどれか。","choices":["6/49","2/7","9/49","1/7"],"answer":4,"explanation":"3/7×2/6=1/7。戻す場合の9/49とは異なる。"},{"id":"yoso-300","field":"確率","question":"赤玉5個・白玉3個の袋から、戻さずに2個取り出す。2個とも赤玉である確率はどれか。","choices":["5/16","15/56","25/64","5/14"],"answer":4,"explanation":"5/8×4/7=5/14。戻す場合の25/64とは異なる。"},{"id":"yoso-301","field":"確率変数と確率分布","question":"B(40, 0.2)に従う確率変数の分散はいくつか。","choices":["1.60","6.40","8.00","2.53"],"answer":2,"explanation":"分散=np(1−p)=40×0.2×0.8=6.40。平均はnp=8.00。"},{"id":"yoso-302","field":"確率変数と確率分布","question":"B(30, 0.1)に従う確率変数の分散はいくつか。","choices":["2.70","1.64","0.30","3.00"],"answer":1,"explanation":"分散=np(1−p)=30×0.1×0.9=2.70。平均はnp=3.00。"},{"id":"yoso-303","field":"確率変数と確率分布","question":"B(10, 0.4)に従う確率変数の分散はいくつか。","choices":["1.55","2.40","4.00","1.60"],"answer":2,"explanation":"分散=np(1−p)=10×0.4×0.6=2.40。平均はnp=4.00。"},{"id":"yoso-304","field":"確率変数と確率分布","question":"V[X]=5のとき、Y=2X+5の分散V[Y]はいくつか。","choices":["10","15","20","25"],"answer":3,"explanation":"V[aX+b]=a²V[X]=4×5=20。定数bは分散に影響しない。"},{"id":"yoso-305","field":"確率変数と確率分布","question":"V[X]=3のとき、Y=-2X−1の分散V[Y]はいくつか。","choices":["12","-7","-6","11"],"answer":1,"explanation":"V[aX+b]=a²V[X]=4×3=12。定数bは分散に影響しない。"},{"id":"yoso-306","field":"確率変数と確率分布","question":"V[X]=5のとき、Y=3X+5の分散V[Y]はいくつか。","choices":["45","50","15","20"],"answer":1,"explanation":"V[aX+b]=a²V[X]=9×5=45。定数bは分散に影響しない。"},{"id":"yoso-307","field":"確率変数と確率分布","question":"確率変数Xが値1, 2, 3をそれぞれ確率0.2, 0.5, 0.3でとるとき、E[X]はいくつか。","choices":["3","2","4.9","2.1"],"answer":4,"explanation":"E[X]=Σx·P(x)=2.1。単純平均2は確率で重みづけしていない。"},{"id":"yoso-308","field":"確率変数と確率分布","question":"確率変数Xが値2, 4, 6をそれぞれ確率0.1, 0.6, 0.3でとるとき、E[X]はいくつか。","choices":["4.4","6","4","20.8"],"answer":1,"explanation":"E[X]=Σx·P(x)=4.4。単純平均4は確率で重みづけしていない。"},{"id":"yoso-309","field":"確率変数と確率分布","question":"確率変数Xが値2, 4, 6をそれぞれ確率0.2, 0.5, 0.3でとるとき、E[X]はいくつか。","choices":["6","4","4.2","19.6"],"answer":3,"explanation":"E[X]=Σx·P(x)=4.2。単純平均4は確率で重みづけしていない。"},{"id":"yoso-310","field":"確率変数と確率分布","question":"確率変数Xが値0, 5, 10をそれぞれ確率0.4, 0.4, 0.2でとるとき、E[X]はいくつか。","choices":["5","4","0","30"],"answer":2,"explanation":"E[X]=Σx·P(x)=4。単純平均5は確率で重みづけしていない。"},{"id":"yoso-311","field":"確率変数と確率分布","question":"XとYが独立で、V[X]=3、V[Y]=9のとき、V[X−3Y]はいくつか。","choices":["30","84","48","-78"],"answer":2,"explanation":"独立なので V=a²V[X]+b²V[Y]=1×3+9×9=84。引き算でも分散は足す。"},{"id":"yoso-312","field":"確率変数と確率分布","question":"XとYが独立で、V[X]=5、V[Y]=2のとき、V[3X−3Y]はいくつか。","choices":["21","0","27","63"],"answer":4,"explanation":"独立なので V=a²V[X]+b²V[Y]=9×5+9×2=63。引き算でも分散は足す。"},{"id":"yoso-313","field":"確率変数と確率分布","question":"XとYが独立で、V[X]=9、V[Y]=2のとき、V[2X+1Y]はいくつか。","choices":["38","20","99","34"],"answer":1,"explanation":"独立なので V=a²V[X]+b²V[Y]=4×9+1×2=38。引き算でも分散は足す。"},{"id":"yoso-314","field":"確率変数と確率分布","question":"平均2のポアソン分布に従う確率変数Xについて、P(X=1)に最も近い値はどれか。","choices":["0.135","0.271","0.541","0.729"],"answer":2,"explanation":"P(X=1)=e^(−2)×2^1/1!=0.271。"},{"id":"yoso-315","field":"確率変数と確率分布","question":"平均1のポアソン分布に従う確率変数Xについて、P(X=1)に最も近い値はどれか。","choices":["0.184","0.632","0.736","0.368"],"answer":4,"explanation":"P(X=1)=e^(−1)×1^1/1!=0.368。"},{"id":"yoso-316","field":"確率変数と確率分布","question":"平均3のポアソン分布に従う確率変数Xについて、P(X=0)に最も近い値はどれか。","choices":["0.950","0.149","0.050","0.025"],"answer":3,"explanation":"P(X=0)=e^(−3)×3^0/0!=0.050。"},{"id":"yoso-317","field":"確率変数と確率分布","question":"B(3, 0.4)に従う確率変数Xについて、P(X=1)はいくつか(小数第3位まで)。","choices":["1.200","0.288","0.144","0.432"],"answer":4,"explanation":"3C1×0.4^1×0.6^2=0.432。"},{"id":"yoso-318","field":"確率変数と確率分布","question":"B(5, 0.4)に従う確率変数Xについて、P(X=3)はいくつか(小数第3位まで)。","choices":["0.640","0.230","0.346","0.023"],"answer":2,"explanation":"5C3×0.4^3×0.6^2=0.230。"},{"id":"yoso-319","field":"確率変数と確率分布","question":"B(3, 0.3)に従う確率変数Xについて、P(X=2)はいくつか(小数第3位まで)。","choices":["0.270","0.441","0.063","0.189"],"answer":4,"explanation":"3C2×0.3^2×0.7^1=0.189。"},{"id":"yoso-320","field":"確率変数と確率分布","question":"B(4, 0.4)に従う確率変数Xについて、P(X=3)はいくつか(小数第3位まで)。","choices":["0.154","0.346","0.256","0.038"],"answer":1,"explanation":"4C3×0.4^3×0.6^1=0.154。"},{"id":"yoso-321","field":"正規分布と標本分布","question":"母標準偏差10の母集団から大きさ49の無作為標本を取る。標本平均の標準誤差はいくつか。","choices":["0.20","2.04","1.43","70.00"],"answer":3,"explanation":"標準誤差=σ/√n=10/7=1.43。"},{"id":"yoso-322","field":"正規分布と標本分布","question":"母標準偏差8の母集団から大きさ16の無作為標本を取る。標本平均の標準誤差はいくつか。","choices":["32.00","0.50","2.00","4.00"],"answer":3,"explanation":"標準誤差=σ/√n=8/4=2.00。"},{"id":"yoso-323","field":"正規分布と標本分布","question":"母標準偏差8の母集団から大きさ25の無作為標本を取る。標本平均の標準誤差はいくつか。","choices":["0.32","1.60","40.00","2.56"],"answer":2,"explanation":"標準誤差=σ/√n=8/5=1.60。"},{"id":"yoso-324","field":"正規分布と標本分布","question":"平均60、標準偏差5の正規分布に従う確率変数Xについて、P(X≥70)に最も近い値はどれか。","choices":["0.011","0.046","0.977","0.023"],"answer":4,"explanation":"z=(70−60)/5=+2。標準正規分布の片側確率は約0.023。"},{"id":"yoso-325","field":"正規分布と標本分布","question":"平均60、標準偏差5の正規分布に従う確率変数Xについて、P(X≥72.5)に最も近い値はどれか。","choices":["0.994","0.012","0.006","0.003"],"answer":3,"explanation":"z=(72.5−60)/5=+2.5。標準正規分布の片側確率は約0.006。"},{"id":"yoso-326","field":"正規分布と標本分布","question":"平均50、標準偏差10の正規分布に従う確率変数Xについて、P(X≥70)に最も近い値はどれか。","choices":["0.023","0.977","0.011","0.046"],"answer":1,"explanation":"z=(70−50)/10=+2。標準正規分布の片側確率は約0.023。"},{"id":"yoso-327","field":"正規分布と標本分布","question":"平均100、標準偏差5の正規分布に従う確率変数Xについて、P(X≥110)に最も近い値はどれか。","choices":["0.977","0.023","0.046","0.011"],"answer":2,"explanation":"z=(110−100)/5=+2。標準正規分布の片側確率は約0.023。"},{"id":"yoso-328","field":"正規分布と標本分布","question":"母平均100、母標準偏差12の母集団から大きさ25の標本を取る。標本平均が102.4以上となる確率に最も近い値はどれか。","choices":["0.159","0.421","0.317","0.841"],"answer":1,"explanation":"標準誤差=12/√25=2.40。z=(102.4−100)/2.40=1.00。P(Z≥z)≈0.159。"},{"id":"yoso-329","field":"正規分布と標本分布","question":"母平均50、母標準偏差20の母集団から大きさ4の標本を取る。標本平均が60以上となる確率に最も近い値はどれか。","choices":["0.841","0.159","0.317","0.309"],"answer":2,"explanation":"標準誤差=20/√4=10.00。z=(60−50)/10.00=1.00。P(Z≥z)≈0.159。"},{"id":"yoso-330","field":"正規分布と標本分布","question":"母平均50、母標準偏差10の母集団から大きさ9の標本を取る。標本平均が56.67以上となる確率に最も近い値はどれか。","choices":["0.045","0.977","0.252","0.023"],"answer":4,"explanation":"標準誤差=10/√9=3.33。z=(56.67−50)/3.33=2.00。P(Z≥z)≈0.023。"},{"id":"yoso-331","field":"正規分布と標本分布","question":"母平均100、母標準偏差20の母集団から大きさ9の標本を取る。標本平均が110以上となる確率に最も近い値はどれか。","choices":["0.309","0.067","0.933","0.134"],"answer":2,"explanation":"標準誤差=20/√9=6.67。z=(110−100)/6.67=1.50。P(Z≥z)≈0.067。"},{"id":"yoso-332","field":"正規分布と標本分布","question":"母比率0.2の母集団から大きさ400の標本を取る。標本比率の標準偏差(標準誤差)に最も近い値はどれか。","choices":["0.022","0.400","0.020","0.0004"],"answer":3,"explanation":"√(p(1−p)/n)=√(0.2×0.8/400)=0.020。"},{"id":"yoso-333","field":"正規分布と標本分布","question":"母比率0.6の母集団から大きさ100の標本を取る。標本比率の標準偏差(標準誤差)に最も近い値はどれか。","choices":["0.0024","0.077","0.490","0.049"],"answer":4,"explanation":"√(p(1−p)/n)=√(0.6×0.4/100)=0.049。"},{"id":"yoso-334","field":"正規分布と標本分布","question":"母比率0.6の母集団から大きさ200の標本を取る。標本比率の標準偏差(標準誤差)に最も近い値はどれか。","choices":["0.0012","0.490","0.035","0.055"],"answer":3,"explanation":"√(p(1−p)/n)=√(0.6×0.4/200)=0.035。"},{"id":"yoso-335","field":"正規分布と標本分布","question":"XとYは独立で、X〜N(40, 16)、Y〜N(50, 25)(N(平均, 分散))のとき、X−Yの分布はどれか。","choices":["N(-10, 81)","N(90, 41)","N(-10, 9)","N(-10, 41)"],"answer":4,"explanation":"平均は40−50=-10。独立なので分散は引き算でも足して16+25=41。"},{"id":"yoso-336","field":"正規分布と標本分布","question":"XとYは独立で、X〜N(50, 4)、Y〜N(30, 16)(N(平均, 分散))のとき、X−Yの分布はどれか。","choices":["N(80, 20)","N(20, 36)","N(20, 20)","N(20, 12)"],"answer":3,"explanation":"平均は50−30=20。独立なので分散は引き算でも足して4+16=20。"},{"id":"yoso-337","field":"正規分布と標本分布","question":"XとYは独立で、X〜N(30, 9)、Y〜N(40, 4)(N(平均, 分散))のとき、X−Yの分布はどれか。","choices":["N(70, 13)","N(-10, 13)","N(-10, 5)","N(-10, 25)"],"answer":2,"explanation":"平均は30−40=-10。独立なので分散は引き算でも足して9+4=13。"},{"id":"yoso-338","field":"正規分布と標本分布","question":"正規母集団から大きさ21の標本を取り、不偏分散をs²、母分散をσ²とする。(n−1)s²/σ²は自由度いくつのχ²分布に従うか。","choices":["22","21","19","20"],"answer":4,"explanation":"自由度はn−1=20。"},{"id":"yoso-339","field":"正規分布と標本分布","question":"正規母集団から大きさ8の標本を取り、不偏分散をs²、母分散をσ²とする。(n−1)s²/σ²は自由度いくつのχ²分布に従うか。","choices":["6","8","9","7"],"answer":4,"explanation":"自由度はn−1=7。"},{"id":"yoso-340","field":"正規分布と標本分布","question":"正規母集団から大きさ16の標本を取り、不偏分散をs²、母分散をσ²とする。(n−1)s²/σ²は自由度いくつのχ²分布に従うか。","choices":["16","15","17","14"],"answer":2,"explanation":"自由度はn−1=15。"},{"id":"yoso-341","field":"統計的推定","question":"母標準偏差5が既知の母集団から大きさ100の標本を取り、標本平均が90であった。母平均の95%信頼区間(z=1.96)はどれか。","choices":["[89.18, 90.82]","[89.02, 90.98]","[80.20, 99.80]","[88.04, 91.96]"],"answer":2,"explanation":"標準誤差=5/√100=0.50。90±1.96×0.50=[89.02, 90.98]。"},{"id":"yoso-342","field":"統計的推定","question":"母標準偏差10が既知の母集団から大きさ36の標本を取り、標本平均が40であった。母平均の95%信頼区間(z=1.96)はどれか。","choices":["[20.40, 59.60]","[33.47, 46.53]","[36.73, 43.27]","[37.26, 42.74]"],"answer":3,"explanation":"標準誤差=10/√36=1.67。40±1.96×1.67=[36.73, 43.27]。"},{"id":"yoso-343","field":"統計的推定","question":"母標準偏差12が既知の母集団から大きさ64の標本を取り、標本平均が55であった。母平均の95%信頼区間(z=1.96)はどれか。","choices":["[52.06, 57.94]","[52.53, 57.47]","[49.12, 60.88]","[31.48, 78.52]"],"answer":1,"explanation":"標準誤差=12/√64=1.50。55±1.96×1.50=[52.06, 57.94]。"},{"id":"yoso-344","field":"統計的推定","question":"母標準偏差20が既知の母集団から大きさ36の標本を取り、標本平均が40であった。母平均の95%信頼区間(z=1.96)はどれか。","choices":["[26.93, 53.07]","[34.52, 45.48]","[0.80, 79.20]","[33.47, 46.53]"],"answer":4,"explanation":"標準誤差=20/√36=3.33。40±1.96×3.33=[33.47, 46.53]。"},{"id":"yoso-345","field":"統計的推定","question":"母標準偏差10が既知のとき、母平均を95%信頼(z=1.96)で誤差±1以内に推定するために必要な最小の標本サイズはいくつか。","choices":["384","385","20","664"],"answer":2,"explanation":"n≥(1.96×10/1)²=384.16。切り上げて385。"},{"id":"yoso-346","field":"統計的推定","question":"母標準偏差10が既知のとき、母平均を95%信頼(z=1.96)で誤差±5以内に推定するために必要な最小の標本サイズはいくつか。","choices":["27","16","15","4"],"answer":2,"explanation":"n≥(1.96×10/5)²=15.37。切り上げて16。"},{"id":"yoso-347","field":"統計的推定","question":"母標準偏差15が既知のとき、母平均を95%信頼(z=1.96)で誤差±4以内に推定するために必要な最小の標本サイズはいくつか。","choices":["55","8","54","94"],"answer":1,"explanation":"n≥(1.96×15/4)²=54.02。切り上げて55。"},{"id":"yoso-348","field":"統計的推定","question":"大きさ100の標本で標本比率が0.3であった。母比率の95%信頼区間(z=1.96、標本比率で標準誤差を近似)はどれか。","choices":["[0.225, 0.375]","[0.182, 0.418]","[0.210, 0.390]","[0.296, 0.304]"],"answer":3,"explanation":"標準誤差=√(0.3×0.7/100)=0.0458。0.3±1.96×0.0458=[0.210, 0.390]。"},{"id":"yoso-349","field":"統計的推定","question":"大きさ900の標本で標本比率が0.5であった。母比率の95%信頼区間(z=1.96、標本比率で標準誤差を近似)はどれか。","choices":["[0.457, 0.543]","[0.473, 0.527]","[0.467, 0.533]","[0.499, 0.501]"],"answer":3,"explanation":"標準誤差=√(0.5×0.5/900)=0.0167。0.5±1.96×0.0167=[0.467, 0.533]。"},{"id":"yoso-350","field":"統計的推定","question":"大きさ200の標本で標本比率が0.5であった。母比率の95%信頼区間(z=1.96、標本比率で標準誤差を近似)はどれか。","choices":["[0.431, 0.569]","[0.498, 0.502]","[0.409, 0.591]","[0.442, 0.558]"],"answer":1,"explanation":"標準誤差=√(0.5×0.5/200)=0.0354。0.5±1.96×0.0354=[0.431, 0.569]。"},{"id":"yoso-351","field":"統計的推定","question":"正規母集団から大きさ16の標本を取り、標本平均25、標本標準偏差10であった。母平均の95%信頼区間はどれか(自由度15のt分布の上側2.5%点は2.131)。","choices":["[19.67, 30.33]","[3.69, 46.31]","[20.10, 29.90]","[23.67, 26.33]"],"answer":1,"explanation":"標準誤差=10/√16=2.50。25±2.131×2.50=[19.67, 30.33]。母分散未知なのでt分布を使う。"},{"id":"yoso-352","field":"統計的推定","question":"正規母集団から大きさ9の標本を取り、標本平均70、標本標準偏差5であった。母平均の95%信頼区間はどれか(自由度8のt分布の上側2.5%点は2.306)。","choices":["[66.16, 73.84]","[58.47, 81.53]","[68.72, 71.28]","[66.73, 73.27]"],"answer":1,"explanation":"標準誤差=5/√9=1.67。70±2.306×1.67=[66.16, 73.84]。母分散未知なのでt分布を使う。"},{"id":"yoso-353","field":"統計的推定","question":"正規母集団から大きさ9の標本を取り、標本平均75、標本標準偏差3であった。母平均の95%信頼区間はどれか(自由度8のt分布の上側2.5%点は2.306)。","choices":["[72.69, 77.31]","[74.23, 75.77]","[73.04, 76.96]","[68.08, 81.92]"],"answer":1,"explanation":"標準誤差=3/√9=1.00。75±2.306×1.00=[72.69, 77.31]。母分散未知なのでt分布を使う。"},{"id":"yoso-354","field":"統計的推定","question":"層A(900人)と層B(600人)からなる母集団から、比例配分の層化抽出で200人を抽出する。層Aから何人抽出するか。","choices":["100","120","80","900"],"answer":2,"explanation":"比例配分なので200×900/1500=120人。"},{"id":"yoso-355","field":"統計的推定","question":"層A(200人)と層B(800人)からなる母集団から、比例配分の層化抽出で200人を抽出する。層Aから何人抽出するか。","choices":["160","200","100","40"],"answer":4,"explanation":"比例配分なので200×200/1000=40人。"},{"id":"yoso-356","field":"統計的推定","question":"層A(500人)と層B(1500人)からなる母集団から、比例配分の層化抽出で200人を抽出する。層Aから何人抽出するか。","choices":["150","100","500","50"],"answer":4,"explanation":"比例配分なので200×500/2000=50人。"},{"id":"yoso-357","field":"統計的推定","question":"独立な2標本で、母分散が36・36、標本サイズが25・16のとき、標本平均の差の標準誤差はいくつか。","choices":["1.33","3.69","1.92","2.70"],"answer":3,"explanation":"標準誤差=√(36/25+36/16)=1.92。"},{"id":"yoso-358","field":"統計的推定","question":"独立な2標本で、母分散が16・16、標本サイズが16・4のとき、標本平均の差の標準誤差はいくつか。","choices":["2.24","1.26","5.00","3.00"],"answer":1,"explanation":"標準誤差=√(16/16+16/4)=2.24。"},{"id":"yoso-359","field":"統計的推定","question":"独立な2標本で、母分散が64・25、標本サイズが16・4のとき、標本平均の差の標準誤差はいくつか。","choices":["10.25","3.20","4.50","2.11"],"answer":2,"explanation":"標準誤差=√(64/16+25/4)=3.20。"},{"id":"yoso-360","field":"統計的推定","question":"独立な2標本で、母分散が25・64、標本サイズが25・4のとき、標本平均の差の標準誤差はいくつか。","choices":["1.75","4.12","5.00","17.00"],"answer":2,"explanation":"標準誤差=√(25/25+64/4)=4.12。"},{"id":"yoso-361","field":"仮説検定","question":"H0:μ=50の検定で、母標準偏差10が既知、n=16、標本平均が57.5のとき、検定統計量zはいくつか。","choices":["0.75","3.00","-3.00","1.50"],"answer":2,"explanation":"z=(57.5−50)/(10/√16)=3.00。"},{"id":"yoso-362","field":"仮説検定","question":"H0:μ=100の検定で、母標準偏差5が既知、n=100、標本平均が99.25のとき、検定統計量zはいくつか。","choices":["1.50","-0.75","-0.15","-1.50"],"answer":4,"explanation":"z=(99.25−100)/(5/√100)=-1.50。"},{"id":"yoso-363","field":"仮説検定","question":"H0:μ=100の検定で、母標準偏差12が既知、n=25、標本平均が103.6のとき、検定統計量zはいくつか。","choices":["0.30","0.75","-1.50","1.50"],"answer":4,"explanation":"z=(103.6−100)/(12/√25)=1.50。"},{"id":"yoso-364","field":"仮説検定","question":"H0:p=0.4の母比率の検定で、n=200、標本比率が0.45のとき、検定統計量z(帰無仮説の下での標準誤差を使用)はいくつか。","choices":["1.44","1.42","41.67","0.10"],"answer":1,"explanation":"z=(0.45−0.4)/√(0.4×0.6/200)=1.44。"},{"id":"yoso-365","field":"仮説検定","question":"H0:p=0.5の母比率の検定で、n=400、標本比率が0.55のとき、検定統計量z(帰無仮説の下での標準誤差を使用)はいくつか。","choices":["2.01","2.00","0.10","80.00"],"answer":2,"explanation":"z=(0.55−0.5)/√(0.5×0.5/400)=2.00。"},{"id":"yoso-366","field":"仮説検定","question":"H0:p=0.5の母比率の検定で、n=400、標本比率が0.45のとき、検定統計量z(帰無仮説の下での標準誤差を使用)はいくつか。","choices":["-0.10","-2.00","-2.01","-80.00"],"answer":2,"explanation":"z=(0.45−0.5)/√(0.5×0.5/400)=-2.00。"},{"id":"yoso-367","field":"仮説検定","question":"H0:μ=50のt検定で、n=25、標本平均が46.4、標本標準偏差が12のとき、t統計量はいくつか。","choices":["-7.50","-1.50","-0.30","1.50"],"answer":2,"explanation":"t=(46.4−50)/(12/√25)=-1.50(自由度24)。"},{"id":"yoso-368","field":"仮説検定","question":"H0:μ=50のt検定で、n=9、標本平均が52、標本標準偏差が4のとき、t統計量はいくつか。","choices":["-1.50","1.50","0.50","4.50"],"answer":2,"explanation":"t=(52−50)/(4/√9)=1.50(自由度8)。"},{"id":"yoso-369","field":"仮説検定","question":"H0:μ=100のt検定で、n=9、標本平均が104.17、標本標準偏差が5のとき、t統計量はいくつか。","choices":["0.83","7.51","2.50","-2.50"],"answer":3,"explanation":"t=(104.17−100)/(5/√9)=2.50(自由度8)。"},{"id":"yoso-370","field":"仮説検定","question":"H0:μ=100のt検定で、n=9、標本平均が102.5、標本標準偏差が5のとき、t統計量はいくつか。","choices":["-1.50","1.50","0.50","4.50"],"answer":2,"explanation":"t=(102.5−100)/(5/√9)=1.50(自由度8)。"},{"id":"yoso-371","field":"仮説検定","question":"4つの区分の観測度数が25, 17, 22, 16(合計80)で、すべての区分の期待度数が等しい(20)と仮定する。適合度のχ²統計量はいくつか。","choices":["2.70","0.68","54.00","0.70"],"answer":1,"explanation":"各区分の偏差は5, -3, 2, -4。Σ(観測−期待)²/期待=2.70。自由度は3。"},{"id":"yoso-372","field":"仮説検定","question":"4つの区分の観測度数が30, 24, 20, 26(合計100)で、すべての区分の期待度数が等しい(25)と仮定する。適合度のχ²統計量はいくつか。","choices":["0.52","2.08","52.00","0.48"],"answer":2,"explanation":"各区分の偏差は5, -1, -5, 1。Σ(観測−期待)²/期待=2.08。自由度は3。"},{"id":"yoso-373","field":"仮説検定","question":"4つの区分の観測度数が22, 24, 26, 28(合計100)で、すべての区分の期待度数が等しい(25)と仮定する。適合度のχ²統計量はいくつか。","choices":["0.32","0.80","0.20","20.00"],"answer":2,"explanation":"各区分の偏差は-3, -1, 1, 3。Σ(観測−期待)²/期待=0.80。自由度は3。"},{"id":"yoso-374","field":"仮説検定","question":"2×2の分割表で、第1行の合計が50、第1列の合計が40、総計が100のとき、独立性の検定における第1行第1列の期待度数はいくつか。","choices":["2000","125","45","20"],"answer":4,"explanation":"期待度数=行合計×列合計/総計=50×40/100=20。"},{"id":"yoso-375","field":"仮説検定","question":"5行3列の分割表に対する独立性のχ²検定の自由度はいくつか。","choices":["8","15","6","14"],"answer":1,"explanation":"自由度=(行数−1)(列数−1)=(5−1)(3−1)=8。"},{"id":"yoso-376","field":"仮説検定","question":"4行4列の分割表に対する独立性のχ²検定の自由度はいくつか。","choices":["9","16","6","15"],"answer":1,"explanation":"自由度=(行数−1)(列数−1)=(4−1)(4−1)=9。"},{"id":"yoso-377","field":"仮説検定","question":"標準正規分布を用いた有意水準5%の両側検定を行う(棄却域の臨界値は±1.96)。検定統計量がz=2.7のとき、結論として最も適切なものはどれか。","choices":["帰無仮説を棄却しない","帰無仮説を棄却する","帰無仮説が正しいことが証明された","対立仮説が誤りであることが証明された"],"answer":2,"explanation":"z=2.7と臨界値1.96を比べる。超えるので棄却する。"},{"id":"yoso-378","field":"仮説検定","question":"標準正規分布を用いた有意水準1%の上側片側検定を行う(棄却域の臨界値は2.326)。検定統計量がz=2.7のとき、結論として最も適切なものはどれか。","choices":["帰無仮説を棄却する","帰無仮説を棄却しない","帰無仮説が正しいことが証明された","対立仮説が誤りであることが証明された"],"answer":1,"explanation":"z=2.7と臨界値2.326を比べる。超えるので棄却する。"},{"id":"yoso-379","field":"仮説検定","question":"標準正規分布を用いた有意水準1%の両側検定を行う(棄却域の臨界値は±2.576)。検定統計量がz=2.4のとき、結論として最も適切なものはどれか。","choices":["帰無仮説が正しいことが証明された","帰無仮説を棄却しない","対立仮説が誤りであることが証明された","帰無仮説を棄却する"],"answer":2,"explanation":"z=2.4と臨界値2.576を比べる。超えないので棄却しない(帰無仮説が正しいと証明されたわけではない)。"},{"id":"yoso-380","field":"仮説検定","question":"標準正規分布を用いた有意水準1%の両側検定を行う(棄却域の臨界値は±2.576)。検定統計量がz=1.8のとき、結論として最も適切なものはどれか。","choices":["帰無仮説を棄却しない","対立仮説が誤りであることが証明された","帰無仮説が正しいことが証明された","帰無仮説を棄却する"],"answer":1,"explanation":"z=1.8と臨界値2.576を比べる。超えないので棄却しない(帰無仮説が正しいと証明されたわけではない)。"},{"id":"yoso-381","field":"回帰分析と分散分析","question":"単回帰でSxx=25、Sxy=25のとき、回帰係数(傾き)はいくつか。","choices":["1","-1","2","25"],"answer":1,"explanation":"傾き=Sxy/Sxx=25/25=1。"},{"id":"yoso-382","field":"回帰分析と分散分析","question":"単回帰でSxx=50、Sxy=50のとき、回帰係数(傾き)はいくつか。","choices":["50","1","-1","2"],"answer":2,"explanation":"傾き=Sxy/Sxx=50/50=1。"},{"id":"yoso-383","field":"回帰分析と分散分析","question":"単回帰で、xの平均が4、yの平均が50、傾きが1のとき、切片はいくつか。","choices":["4","50","46","54"],"answer":3,"explanation":"回帰直線は(x̄, ȳ)を通る。切片=ȳ−b·x̄=50−(1)×4=46。"},{"id":"yoso-384","field":"回帰分析と分散分析","question":"単回帰で、xの平均が2、yの平均が30、傾きが2のとき、切片はいくつか。","choices":["30","34","28","26"],"answer":4,"explanation":"回帰直線は(x̄, ȳ)を通る。切片=ȳ−b·x̄=30−(2)×2=26。"},{"id":"yoso-385","field":"回帰分析と分散分析","question":"回帰分析で、総平方和が100、残差平方和が64のとき、決定係数R²はいくつか。","choices":["0.60","0.64","0.32","0.36"],"answer":4,"explanation":"R²=1−残差平方和/総平方和=1−64/100=0.36。"},{"id":"yoso-386","field":"回帰分析と分散分析","question":"回帰分析で、総平方和が500、残差平方和が400のとき、決定係数R²はいくつか。","choices":["0.80","0.20","0.45","0.40"],"answer":2,"explanation":"R²=1−残差平方和/総平方和=1−400/500=0.20。"},{"id":"yoso-387","field":"回帰分析と分散分析","question":"回帰分析で、総平方和が400、残差平方和が320のとき、決定係数R²はいくつか。","choices":["0.20","0.45","0.40","0.80"],"answer":1,"explanation":"R²=1−残差平方和/総平方和=1−320/400=0.20。"},{"id":"yoso-388","field":"回帰分析と分散分析","question":"一元配置分散分析で、3群・各群5個のデータ。群間平方和が60、群内平方和が150のとき、F値はいくつか。","choices":["0.07","0.42","0.40","2.40"],"answer":4,"explanation":"F=(群間平方和/2)/(群内平方和/12)=(60/2)/(150/12)=2.40。"},{"id":"yoso-389","field":"回帰分析と分散分析","question":"一元配置分散分析で、4群・各群6個のデータ。群間平方和が180、群内平方和が60のとき、F値はいくつか。","choices":["0.45","0.05","20.00","3.00"],"answer":3,"explanation":"F=(群間平方和/3)/(群内平方和/20)=(180/3)/(60/20)=20.00。"},{"id":"yoso-390","field":"回帰分析と分散分析","question":"一元配置分散分析で、4群・各群5個のデータ。群間平方和が120、群内平方和が60のとき、F値はいくつか。","choices":["0.09","0.38","2.00","10.67"],"answer":4,"explanation":"F=(群間平方和/3)/(群内平方和/16)=(120/3)/(60/16)=10.67。"},{"id":"yoso-391","field":"回帰分析と分散分析","question":"回帰直線がy=5+3xのとき、x=2で観測値がy=13であった。残差(観測値−予測値)はいくつか。","choices":["2","13","11","-2"],"answer":1,"explanation":"予測値=11。残差=観測値−予測値=13−11=2。"},{"id":"yoso-392","field":"回帰分析と分散分析","question":"回帰直線がy=10+3xのとき、x=4での予測値はいくつか。","choices":["12","22","26","14"],"answer":2,"explanation":"y=10+3×4=22。"},{"id":"yoso-393","field":"回帰分析と分散分析","question":"回帰直線がy=-3+0.5xのとき、x=4で観測値がy=1であった。残差(観測値−予測値)はいくつか。","choices":["1","2","-2","-1"],"answer":2,"explanation":"予測値=-1。残差=観測値−予測値=1−-1=2。"},{"id":"yoso-394","field":"回帰分析と分散分析","question":"回帰直線がy=10+2xのとき、x=2で観測値がy=18であった。残差(観測値−予測値)はいくつか。","choices":["4","-4","14","18"],"answer":1,"explanation":"予測値=14。残差=観測値−予測値=18−14=4。"},{"id":"yoso-395","field":"回帰分析と分散分析","question":"n=20の観測値による単回帰分析で、残差の自由度はいくつか。","choices":["19","20","17","18"],"answer":4,"explanation":"自由度=n−2=18(切片と傾きの2つを推定)。"},{"id":"yoso-396","field":"回帰分析と分散分析","question":"4群・各群5個(計20個)の一元配置分散分析で、群内(残差)の自由度はいくつか。","choices":["3","20","16","19"],"answer":3,"explanation":"群内の自由度=N−群数=20−4=16。"},{"id":"yoso-397","field":"回帰分析と分散分析","question":"n=20の観測値と説明変数2個の重回帰分析(切片あり)で、残差の自由度はいくつか。","choices":["17","18","16","19"],"answer":1,"explanation":"自由度=n−p−1=20−2−1=17。"},{"id":"yoso-398","field":"回帰分析と分散分析","question":"単回帰分析で、n=10、決定係数R²=0.2のとき、回帰の有意性を検定するF値はいくつか。","choices":["2.00","0.25","1.00","1.60"],"answer":1,"explanation":"F=R²/(1−R²)×(n−2)=0.2/0.8×8=2.00。"},{"id":"yoso-399","field":"回帰分析と分散分析","question":"単回帰分析で、n=10、決定係数R²=0.8のとき、回帰の有意性を検定するF値はいくつか。","choices":["32.00","16.00","4.00","6.40"],"answer":1,"explanation":"F=R²/(1−R²)×(n−2)=0.8/0.2×8=32.00。"},{"id":"yoso-400","field":"回帰分析と分散分析","question":"単回帰分析で、n=22、決定係数R²=0.8のとき、回帰の有意性を検定するF値はいくつか。","choices":["4.00","16.00","40.00","80.00"],"answer":4,"explanation":"F=R²/(1−R²)×(n−2)=0.8/0.2×20=80.00。"}];
